    if (lay <= laytrop) {
        float colh2o = FS(SL_COLH2O);
        int jpv = IS(SI_JP);

        RlwSpecB35 s0 = rlw_b35_spec(colh2o, FS(SL_RAT_H2OCO2), colco2,
                                     oneminus, 8.0f);
