    // GPU_BAND_TABS[13] = absa(585,ng), selfref(10,ng), forref(4,ng),
    //                     ka_mco2(9,19,ng), ka_mco(9,19,ng),
    //                     kb_mo3(19,ng), fracrefa(ng,9), fracrefb(ng)
    const float* absa = tabs[0];
