                                  rlw_pow(RLW_SU(ratco2, 2.0f), 0.68f));
            adjcolco2 = RLW_MU(RLW_MU(RLW_MU(adjfac, 3.55e-4f),
                                      FS(SL_COLDRY)), 1.e-20f);
