        if (specparm_mco >= oneminus) specparm_mco = oneminus;
        float specmult_mco = RLW_MU(8.0f, specparm_mco);
        int jmco = 1 + (int)specmult_mco;
        float fmco = fmodf(specmult_mco, 1.0f);

