                                       chi_mls[3 + 7 * 4]);
        // P = 1053. (Level 1): chi_mls(1,1)/chi_mls(4,1)
        float refrat_m_a = RLW_DV(chi_mls[0 + 7 * 0], chi_mls[3 + 7 * 0]);
        // P = 706. (Level 3): chi_mls(1,3)/chi_mls(4,3)
