    double xd = (double) x;
    double z = DMUL(__longlong_as_double(C_EXP2F_MISC[2]), xd);
    double kd = DADD(z, shift);
    unsigned long long ki = (unsigned long long) __double_as_longlong(kd);
    kd = DSUB(kd, shift);
    double r = DSUB(z, kd);

