__device__ void snowfall(Col *c, float dt, float qsnow, float snowhin, float sfctmp)
{
    int newnode = 0;

    if (c->isnow == 0 && qsnow > SN_K_ZERO) {
        c->snowh = FADD(c->snowh, FMUL(snowhin, dt));
        c->sneqv = FADD(c->sneqv, FMUL(qsnow, dt));
