                    SNICE(j - 1) = FADD(SNICE(j - 1), SNICE(j));
                    DZSNSO(j - 1) = FADD(DZSNSO(j - 1), DZSNSO(j));
                } else {
                    if (SNICE(j) >= SN_K_ZERO) {
