    int niter = 3;                                                   // :7440
    if (FMUL(pddum, dt) > FMUL(dz[0], par[P_SMCMAX])) niter *= 2;    // :7443
    float dtfine = FDIV(dt, (float) niter);                          // :7449

    float qdrain_save = K_ZERO, runsrf_save = K_ZERO;                // :7453
    float qdrain = K_ZERO;
