    const float* fracrefb = tabs[7];
    const int nspa1 = 1, nspb1 = 1, ng1 = 10, gs = 0;

    if (lay <= laytrop) {
        int ind0 = ((IS(SI_JP) - 1) * 5 + (IS(SI_JT) - 1)) * nspa1 + 1;
