                                       A2(absb, 235, ind0 + 1, ig)));
            tmaj = RLW_AD(tmaj, RLW_MU(FS(SL_FAC01),
                                       A2(absb, 235, ind1, ig)));
            tmaj = RLW_AD(tmaj, RLW_MU(FS(SL_FAC11),
                                       A2(absb, 235, ind1 + 1, ig)));
            float t = RLW_MU(FS(SL_COLO3), tmaj);
            t = RLW_AD(t, RLW_MU(adjcolco2, absco2));
