        int indm = IS(SI_INDMINOR);
        for (int ig = gpoint; ig <= ng13; ig += 16) {
            float abso3 = RLW_AD(A2(kb_mo3, 19, indm, ig),
                RLW_MU(FS(SL_MINORFRAC),
