// is the minimum previous upper index across ALL columns, not this column.
extern "C" __global__ void ozone_min_upper(int nc,int nl,const int *upper,int *start) {
    if(blockIdx.x*blockDim.x+threadIdx.x != 0) return;
    int low=nl;
