            float t = RLW_AD(0.0f, RLW_MU(WXS(2), cfc11adj[ig - 1]));
            t = RLW_AD(t, RLW_MU(WXS(3), cfc12[ig - 1]));
            TAUG(gs + ig) = t;
            FRACS(gs + ig) = fracrefa[ig - 1];
        }
    }
