extern "C" __global__ void hex_nonfinite_words_4(
            const unsigned int* words, unsigned long long count,
            unsigned int* flags, unsigned int field) {
            unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
            unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;
            for (; i < count; i += stride) {
                if ((words[i] & 0x7f800000U) == 0x7f800000U) {
                    atomicExch(flags + field, 1U);
                    return;
                }
            }
        }

extern "C" __global__ void noahmp_copy_slots(unsigned int* out, int n, const unsigned int* v0, const unsigned int* v1, const unsigned int* v2, const unsigned int* v3, const unsigned int* v4, const unsigned int* v5, const unsigned int* v6, const unsigned int* v7, const unsigned int* v8, const unsigned int* v9, const unsigned int* v10) { int c = blockDim.x*blockIdx.x+threadIdx.x; if(c>=n) return; out[(long long)c*44+0] = v0[(long long)c*(7)+(0)];
out[(long long)c*44+1] = v0[(long long)c*(7)+(1)];
out[(long long)c*44+2] = v0[(long long)c*(7)+(2)];
out[(long long)c*44+3] = v0[(long long)c*(7)+(3)];
out[(long long)c*44+4] = v0[(long long)c*(7)+(4)];
out[(long long)c*44+5] = v0[(long long)c*(7)+(5)];
