    if (c->sneqv > K_5000) {
        float bdsnow = FDIV(SNICE(0), DZSNSO(0));
        *snoflow = FSUB(c->sneqv, K_5000);
        SNICE(0) = FSUB(SNICE(0), *snoflow);
        DZSNSO(0) = FSUB(DZSNSO(0), FDIV(*snoflow, bdsnow));
        *snoflow = FDIV(*snoflow, dt);
