    extern "C" __global__ void cupy_multiply__float32_float32_float32(const CArray<float, 2, 0, 1> _raw_in0, const CArray<float, 2, 0, 1> _raw_in1, CArray<float, 2, 1, 1> _raw_out0, CIndexer<2, 1> _ind) {
