    real tmpch = r_log(DV(SU(zlvl, zpd), z0h));                    // :4655
    real tmpcm2 = r_log(DV(AD(2.0f, z0m), z0m));                   // :4656
    real tmpch2 = r_log(DV(AD(2.0f, z0h), z0h));                   // :4657

