        real tmp1 = DV(MU(MU(NMP_VKC, DV(NMP_GRAV, tvir)), h),
                       MU(rhoair, NMP_CPAIR));                     // :4666
        if (fabsf(tmp1) <= mpe) tmp1 = mpe;                        // :4667
