#define NMP_STOMATA_NITER 3

__device__ real nmp_f1(real ab, real tc)                           // :5074
{
    return r_pow(ab, DV(SU(tc, 25.0f), 10.0f));
}

__device__ real nmp_f2(real tc)                                    // :5075
{
