typedef min_max_st<type_in0_raw> _type_reduce;
extern "C" __global__ void cupy_min(const CArray<float, 1, 1, 1> _raw_in0, CArray<float, 1, 1, 1> _raw_out0, CIndexer<1, 1> _in_ind, CIndexer<1, 1> _out_ind, const int _block_stride) {
