    real a[NMP_NLAY], b[NMP_NLAY], c[NMP_NLAY], d[NMP_NLAY];
    real p[NMP_NLAY], del[NMP_NLAY];
    for (int i = 0; i < NMP_NLAY; ++i) {
        a[i] = x[i];
        b[i] = x[NMP_NLAY + i];
        c[i] = x[2 * NMP_NLAY + i];
        d[i] = x[3 * NMP_NLAY + i];
        p[i] = 0.0f;
        del[i] = 0.0f;
    }

    c[NMP_NSOIL + NMP_OFF] = 0.0f;                                 // :5565
