    real snicev[NMP_NSNOW], snliqv[NMP_NSNOW], epore[NMP_NSNOW];
    noahmp_csnow_core(isnow, snice, snliq, dzsnso,
                      tksno, cvsno, snicev, snliqv, epore);        // :2451

    for (int k = isnow + 1; k <= 0; ++k) {                         // :2454-2457
        int j = k + NMP_OFF;
