    for (int i = 0; i < NMP_NLAY; ++i) {
        y[i] = df[i];
        y[NMP_NLAY + i] = hcpct[i];
        y[2 * NMP_NLAY + 3 * NMP_NSNOW + i] = fact[i];
    }
