                if (tk <= W_T0C) {
                    value = wmax(W_QMIN, qck);
                    source = (praut + pracw + paacw + paacw) * dtcld;
                    if (source > value) {
                        factor = value / source;
                        praut = praut * factor;
                        pracw = pracw * factor;
                        paacw = paacw * factor;
                    }
                    value = wmax(W_QMIN, qik);
                    source = (psaut - pigen - pidep + praci + psaci + pgaci) * dtcld;
                    if (source > value) {
                        factor = value / source;
                        psaut = psaut * factor;
                        pigen = pigen * factor;
                        pidep = pidep * factor;
                        praci = praci * factor;
                        psaci = psaci * factor;
                        pgaci = pgaci * factor;
                    }
                    value = wmax(W_QMIN, qrk);
                    source = (-praut - prevp - pracw + piacr + psacr + pgacr) * dtcld;
                    if (source > value) {
                        factor = value / source;
                        praut = praut * factor;
                        prevp = prevp * factor;
                        pracw = pracw * factor;
                        piacr = piacr * factor;
                        psacr = psacr * factor;
                        pgacr = pgacr * factor;
                    }
                    value = wmax(W_QMIN, qsk);
                    source = -((psdep + psaut - pgaut + paacw + piacr * delta3
                                + praci * delta3 - pracs * (1.0f - delta2)
                                + psacr * delta2 + psaci - pgacs) * dtcld);
                    if (source > value) {
                        factor = value / source;
                        psdep = psdep * factor;
                        psaut = psaut * factor;
                        pgaut = pgaut * factor;
                        paacw = paacw * factor;
                        piacr = piacr * factor;
                        praci = praci * factor;
                        psaci = psaci * factor;
                        pracs = pracs * factor;
                        psacr = psacr * factor;
                        pgacs = pgacs * factor;
                    }
                    value = wmax(W_QMIN, qgk);
                    source = -((pgdep + pgaut
                                + piacr * (1.0f - delta3) + praci * (1.0f - delta3)
                                + psacr * (1.0f - delta2) + pracs * (1.0f - delta2)
                                + pgaci + paacw + pgacr + pgacs) * dtcld);
                    if (source > value) {
                        factor = value / source;
                        pgdep = pgdep * factor;
                        pgaut = pgaut * factor;
                        piacr = piacr * factor;
                        praci = praci * factor;
                        psacr = psacr * factor;
                        pracs = pracs * factor;
                        paacw = paacw * factor;
                        pgaci = pgaci * factor;
                        pgacr = pgacr * factor;
                        pgacs = pgacs * factor;
                    }
                    const float work2u = -(prevp + psdep + pgdep + pigen + pidep);
                    qk = qk + work2u * dtcld;
                    qck = wmax(qck - (praut + pracw + paacw + paacw) * dtcld, 0.0f);
                    qrk = wmax(qrk + (praut + pracw + prevp - piacr - pgacr
                                      - psacr) * dtcld, 0.0f);
                    qik = wmax(qik - (psaut + praci + psaci + pgaci - pigen
                                      - pidep) * dtcld, 0.0f);
                    qsk = wmax(qsk + (psdep + psaut + paacw - pgaut + piacr * delta3
                                      + praci * delta3 + psaci - pgacs
                                      - pracs * (1.0f - delta2) + psacr * delta2)
                                     * dtcld, 0.0f);
