                    source = (praut + pracw + paacw + paacw) * dtcld;
                    if (source > value) {
                        factor = value / source;
                        praut = praut * factor;
                        pracw = pracw * factor;
                        paacw = paacw * factor;
                    }
                    value = wmax(W_QMIN, qrk);
                    source = (-paacw - praut + pseml + pgeml - pracw - paacw - prevp)
                           * dtcld;
                    if (source > value) {
                        factor = value / source;
                        praut = praut * factor;
                        prevp = prevp * factor;
                        pracw = pracw * factor;
                        paacw = paacw * factor;
                        pseml = pseml * factor;
                        pgeml = pgeml * factor;
                    }
                    value = wmax(W_QCRMIN, qsk);
                    source = (pgacs - pseml - psevp) * dtcld;
                    if (source > value) {
                        factor = value / source;
                        pgacs = pgacs * factor;
                        psevp = psevp * factor;
                        pseml = pseml * factor;
                    }
                    value = wmax(W_QCRMIN, qgk);
                    source = -((pgacs + pgevp + pgeml) * dtcld);
                    if (source > value) {
                        factor = value / source;
                        pgacs = pgacs * factor;
                        pgevp = pgevp * factor;
                        pgeml = pgeml * factor;
                    }
