  double s1 = gt_tanf_s[1 - (i & 1)];
  double r1 = __ddiv_rn(__dsub_rn(__dmul_rn(n, s1), __dmul_rn(d, s0)), __dadd_rn(__dmul_rn(n, s0), __dmul_rn(d, s1)));
  gt_u64 tail = (gt_as_u64(r1) + 7) & ((~0ULL) >> 35);
  if (tail <= 14)
  {
    /* table gt_tanf_st */;
    gt_u32 ax = t & ((~0u) >> 1);
    gt_u32 sgn = t >> 31;
    for (int j = 0; j < 8; j++)
    {
      if (__float_as_uint(gt_tanf_st[j].arg) == ax)
      {
        if (sgn)
          return __fsub_rn(-gt_tanf_st[j].rh, gt_tanf_st[j].rl);
        else
          return __fadd_rn(gt_tanf_st[j].rh, gt_tanf_st[j].rl);
      }
    }

  }
  return gt_d2f(r1);
}


#endif


#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

__device__ __forceinline__ unsigned int prep_positive_q_bits_v841(
    const float raw)
{
    const unsigned int bits = __float_as_uint(raw);
    return (bits & 0x80000000u) == 0u ? bits : 0u;
}

__device__ __forceinline__ float prep_positive_q_v841(const float raw)
{
    return __uint_as_float(prep_positive_q_bits_v841(raw));
}

__device__ __forceinline__ bool prep_finite_bits_v841(const float raw)
{
    return (__float_as_uint(raw) & 0x7fffffffu) < 0x7f800000u;
}

__device__ __forceinline__ bool prep_negative_nonzero_bits_v841(
    const float raw)
{
    const unsigned int bits = __float_as_uint(raw);
    return (bits & 0x80000000u) != 0u
        && (bits & 0x7fffffffu) != 0u;
}

extern "C" __global__ void prep_mass_v841_f32(
    const int nlev, const int ncells, const int nspecies, const float rvord,
    const float *rho_zz, const float *theta_m, const float *scalars,
    const float *exner, const float *pressure_base, const float *pressure_p,
    const float *zgrid, const float *zz, float *const *qout, float *zz_p,
    float *rho_dry, float *rho_p, float *th_p, float *t_p, float *pi_p,
    float *pres_p, float *zmid_p, float *dz_p, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int plane = nlev * ncells;
    // qout is a DEVICE table of per-species output pointers, sized by the
    // scheme's species row, in the row's order.  It replaces six welded
    // parameters; the arithmetic below is unchanged, which is what the
    // WSM6 byte-identity arm measures.  Slot 0 is water vapour by the row's
    // own invariant -- the moist density, the dry-theta conversion, the
    // NoahMP sounding and the interface extrapolation all read it.
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        for (int s = 0; s < nspecies; ++s) {
            const float raw = scalars[s * plane + i];
            if (!prep_finite_bits_v841(raw)) atomicExch(invalid, 1);
            qout[s][i] = prep_positive_q_v841(raw);
        }
        const float qv = qout[0][i];
        zz_p[i] = zz[i];
        const float dry_rho = mpas_mul(zz[i], rho_zz[i]);
        rho_dry[i] = dry_rho;
        rho_p[i] = mpas_mul(dry_rho, mpas_add(1.0f, qv));
        const float denominator = mpas_add(1.0f, mpas_mul(rvord, qv));
        th_p[i] = mpas_div(theta_m[i], denominator);
        t_p[i] = mpas_mul(th_p[i], exner[i]);
        pi_p[i] = exner[i];
        pres_p[i] = mpas_add(pressure_p[i], pressure_base[i]);
        const float bottom = zgrid[k * ncells + cell];
        const float top = zgrid[(k + 1) * ncells + cell];
        zmid_p[i] = mpas_mul(0.5f, mpas_add(top, bottom));
        dz_p[i] = mpas_sub(top, bottom);
        if (!isfinite(rho_zz[i]) || rho_zz[i] <= 0.0f
                || !isfinite(theta_m[i]) || theta_m[i] <= 0.0f
                || !isfinite(zz[i]) || !isfinite(exner[i])
                || !isfinite(pressure_p[i]) || !isfinite(pressure_base[i]))
            atomicExch(invalid, 1);
    }
}

extern "C" __global__ void reconstruct_winds_v841_f32(
    const int nlev, const int ncells, const int nedges, const int maxedges,
    const float *normal_velocity, const int *edges_on_cell,
    const int *n_edges_on_cell, const float *coeffs_reconstruct,
    const float *lat_cell, const float *lon_cell,
    const int *sealed_edges_on_cell, const int *sealed_n_edges_on_cell,
    const float *sealed_coeffs_reconstruct,
    const float *sealed_lat_cell, const float *sealed_lon_cell,
    float *x, float *y, float *z, float *u_p, float *v_p, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    bool geometry_changed =
        n_edges_on_cell[cell] != sealed_n_edges_on_cell[cell]
        || __float_as_uint(lat_cell[cell])
            != __float_as_uint(sealed_lat_cell[cell])
        || __float_as_uint(lon_cell[cell])
            != __float_as_uint(sealed_lon_cell[cell]);
    for (int slot = 0; slot < maxedges; ++slot) {
        const int edge_index = cell * maxedges + slot;
        const int coeff_index = edge_index * 3;
        geometry_changed = geometry_changed
            || edges_on_cell[edge_index] != sealed_edges_on_cell[edge_index]
            || __float_as_uint(coeffs_reconstruct[coeff_index])
                != __float_as_uint(sealed_coeffs_reconstruct[coeff_index])
            || __float_as_uint(coeffs_reconstruct[coeff_index + 1])
                != __float_as_uint(sealed_coeffs_reconstruct[coeff_index + 1])
            || __float_as_uint(coeffs_reconstruct[coeff_index + 2])
                != __float_as_uint(sealed_coeffs_reconstruct[coeff_index + 2]);
    }
    if (geometry_changed) {
        atomicExch(invalid, 1);
        return;
    }
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        x[i] = 0.0f;
        y[i] = 0.0f;
        z[i] = 0.0f;
    }
    const int count = n_edges_on_cell[cell];
    if (count < 0 || count > maxedges) {
        atomicExch(invalid, 1);
        return;
    }
    for (int slot = 0; slot < count; ++slot) {
        const int edge = edges_on_cell[cell * maxedges + slot];
        if (edge < 0 || edge >= nedges) {
            atomicExch(invalid, 1);
            continue;
        }
        const int ci = (cell * maxedges + slot) * 3;
        const float cx = coeffs_reconstruct[ci];
        const float cy = coeffs_reconstruct[ci + 1];
        const float cz = coeffs_reconstruct[ci + 2];
        if (!isfinite(cx) || !isfinite(cy) || !isfinite(cz))
            atomicExch(invalid, 1);
        for (int k = 0; k < nlev; ++k) {
            const int i = k * ncells + cell;
            const float value = normal_velocity[k * nedges + edge];
            if (!isfinite(value)) atomicExch(invalid, 1);
            x[i] = mpas_add(x[i], mpas_mul(cx, value));
            y[i] = mpas_add(y[i], mpas_mul(cy, value));
            z[i] = mpas_add(z[i], mpas_mul(cz, value));
        }
    }
    const float clat = glibc_cosf(lat_cell[cell]);
    const float slat = glibc_sinf(lat_cell[cell]);
    const float clon = glibc_cosf(lon_cell[cell]);
    const float slon = glibc_sinf(lon_cell[cell]);
    if (!isfinite(clat) || !isfinite(slat) || !isfinite(clon) || !isfinite(slon))
        atomicExch(invalid, 1);
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        u_p[i] = mpas_add(
            mpas_mul(mpas_sub(0.0f, x[i]), slon), mpas_mul(y[i], clon));
        const float horizontal = mpas_add(
            mpas_mul(x[i], clon), mpas_mul(y[i], slon));
        v_p[i] = mpas_add(
            mpas_mul(mpas_sub(0.0f, horizontal), slat), mpas_mul(z[i], clat));
    }
}

extern "C" __global__ void prep_noahmp_sounding_v841_f32(
    const int nlev, const int ncells, const float rvord,
    const float *raw_qv, const float *theta_m, const float *exner,
    const float *pressure_base, const float *pressure_p,
    const float *zgrid, const float *u_p, const float *v_p,
    float *dz8w, float *qv_curr, float *t_phy, float *u_phy,
    float *v_phy, float *p8w, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        const float qraw = raw_qv[i];
        const float thickness = mpas_sub(
            zgrid[i + ncells], zgrid[i]);
        const float denominator = mpas_add(
            1.0f, mpas_mul(rvord, qraw));
        const float temperature = mpas_mul(
            mpas_div(theta_m[i], denominator), exner[i]);
        dz8w[i] = thickness;
        qv_curr[i] = qraw;
        t_phy[i] = temperature;
        u_phy[i] = u_p[i];
        v_phy[i] = v_p[i];
        if (!isfinite(qraw) || !isfinite(temperature)
                || temperature <= 0.0f || !isfinite(thickness)
                || thickness <= 0.0f || !isfinite(u_p[i])
                || !isfinite(v_p[i]))
            atomicExch(invalid, 1);
    }

    float z0 = zgrid[cell];
    float z1 = mpas_mul(
        0.5f, mpas_add(zgrid[cell], zgrid[ncells + cell]));
    float z2 = mpas_mul(
        0.5f, mpas_add(zgrid[ncells + cell], zgrid[2 * ncells + cell]));
    float w1 = mpas_div(mpas_sub(z0, z2), mpas_sub(z1, z2));
    float w2 = mpas_sub(1.0f, w1);
    float totm = mpas_add(pressure_p[cell], pressure_base[cell]);
    float totp = mpas_add(
        pressure_p[ncells + cell], pressure_base[ncells + cell]);
    p8w[cell] = mpas_add(mpas_mul(w1, totm), mpas_mul(w2, totp));
    for (int k = 1; k < nlev; ++k) {
        const int i = k * ncells + cell;
        totm = mpas_add(pressure_p[i - ncells], pressure_base[i - ncells]);
        totp = mpas_add(pressure_p[i], pressure_base[i]);
        const float mult = mpas_div(
            1.0f,
            mpas_sub(zgrid[i + ncells], zgrid[i - ncells]));
        const float fzm = mpas_mul(
            mult, mpas_sub(zgrid[i], zgrid[i - ncells]));
        const float fzp = mpas_mul(
            mult, mpas_sub(zgrid[i + ncells], zgrid[i]));
        p8w[i] = mpas_add(mpas_mul(fzm, totp), mpas_mul(fzp, totm));
    }
    for (int k = 0; k < nlev; ++k) {
        const float value = p8w[k * ncells + cell];
        if (!isfinite(value) || value <= 0.0f)
            atomicExch(invalid, 1);
    }
}

extern "C" __global__ void prep_interfaces_v841_f32(
    const int nlev, const int ncells, const float gravity,
    const float *rho_zz, const float *zz, const float *qv_p,
    const float *pres_p, const float *t_p, const float *rho_p,
    const float *dz_p, const float *zgrid, const float *w,
    float *w_p, float *z_p, float *t2_p, float *pres2_p,
    float *pres_hyd_p, float *pres2_hyd_p, float *pres_hydd_p,
    float *pres2_hydd_p, float *psfc_p, float *psfc_hyd_p,
    float *psfc_hydd_p, float *znu_p, float *znu_hyd_p,
    float *plrad, int *invalid, const float *pressure_perturbation, const float *pressure_base, float *weights_minus, float *weights_plus)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k <= nlev; ++k) {
        const int i = k * ncells + cell;
        w_p[i] = w[i];
        z_p[i] = zgrid[i];
    }
    const float tem1 = mpas_sub(zgrid[ncells + cell], zgrid[cell]);
    const float tem2 = mpas_sub(zgrid[2 * ncells + cell], zgrid[ncells + cell]);
    const float rho1 = mpas_mul(
        mpas_mul(rho_zz[cell], zz[cell]), mpas_add(1.0f, qv_p[cell]));
    const float rho2 = mpas_mul(
        mpas_mul(rho_zz[ncells + cell], zz[ncells + cell]),
        mpas_add(1.0f, qv_p[ncells + cell]));
    const float correction = mpas_div(
        mpas_mul(mpas_mul(0.5f, mpas_sub(rho2, rho1)), tem1),
        mpas_add(tem1, tem2));
    const float hydro = mpas_mul(
        mpas_mul(mpas_mul(0.5f, gravity), tem1),
        mpas_sub(rho1, correction));
    psfc_p[cell] = mpas_add(mpas_add(hydro, pressure_perturbation[cell]), pressure_base[cell]);
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        znu_p[i] = mpas_div(pres_p[i], psfc_p[cell]);
    }

    for (int k = 1; k < nlev; ++k) {
        const float inverse = mpas_div(
            1.0f, mpas_sub(zgrid[(k + 1) * ncells + cell],
                           zgrid[(k - 1) * ncells + cell]));
        const float fzm = mpas_mul(
            mpas_sub(zgrid[k * ncells + cell],
                     zgrid[(k - 1) * ncells + cell]), inverse);
        const float fzp = mpas_mul(
            mpas_sub(zgrid[(k + 1) * ncells + cell],
                     zgrid[k * ncells + cell]), inverse);
        const int i = k * ncells + cell;
        weights_minus[i] = fzm; weights_plus[i] = fzp;
        t2_p[i] = mpas_add(
            mpas_mul(fzm, t_p[i]), mpas_mul(fzp, t_p[i - ncells]));
        pres2_p[i] = mpas_add(
            mpas_mul(fzm, pres_p[i]), mpas_mul(fzp, pres_p[i - ncells]));
    }

    const int top = nlev * ncells + cell;
    float z0 = zgrid[top];
    float z1 = mpas_mul(0.5f, mpas_add(zgrid[top], zgrid[top - ncells]));
    float z2 = mpas_mul(
        0.5f, mpas_add(zgrid[top - ncells], zgrid[top - 2 * ncells]));
    float w1 = mpas_div(mpas_sub(z0, z2), mpas_sub(z1, z2));
    float w2 = mpas_sub(1.0f, w1);
    t2_p[top] = mpas_add(
        mpas_mul(w1, t_p[top - ncells]),
        mpas_mul(w2, t_p[top - 2 * ncells]));
    pres2_p[top] = gfk_exp_fma(mpas_add(
        mpas_mul(w1, gfk_log(pres_p[top - ncells])),
        mpas_mul(w2, gfk_log(pres_p[top - 2 * ncells]))));

    z0 = zgrid[cell];
    z1 = mpas_mul(0.5f, mpas_add(zgrid[cell], zgrid[ncells + cell]));
    z2 = mpas_mul(
        0.5f, mpas_add(zgrid[ncells + cell], zgrid[2 * ncells + cell]));
    w1 = mpas_div(mpas_sub(z0, z2), mpas_sub(z1, z2));
    w2 = mpas_sub(1.0f, w1);
    t2_p[cell] = mpas_add(mpas_mul(w1, t_p[cell]),
                          mpas_mul(w2, t_p[ncells + cell]));
    pres2_p[cell] = mpas_add(mpas_mul(w1, pres_p[cell]),
                             mpas_mul(w2, pres_p[ncells + cell]));

    pres2_hyd_p[top] = pres2_p[top];
    pres2_hydd_p[top] = pres2_p[top];
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = k * ncells + cell;
        const float rho_a = mpas_div(rho_p[i], mpas_add(1.0f, qv_p[i]));
        pres2_hyd_p[i] = mpas_add(
            pres2_hyd_p[i + ncells],
            mpas_mul(mpas_mul(gravity, rho_p[i]), dz_p[i]));
        pres2_hydd_p[i] = mpas_add(
            pres2_hydd_p[i + ncells],
            mpas_mul(mpas_mul(gravity, rho_a), dz_p[i]));
    }
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = k * ncells + cell;
        pres_hyd_p[i] = mpas_mul(
            0.5f, mpas_add(pres2_hyd_p[i + ncells], pres2_hyd_p[i]));
        pres_hydd_p[i] = mpas_mul(
            0.5f, mpas_add(pres2_hydd_p[i + ncells], pres2_hydd_p[i]));
    }
    psfc_hyd_p[cell] = pres2_hyd_p[cell];
    psfc_hydd_p[cell] = pres2_hydd_p[cell];
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = k * ncells + cell;
        znu_hyd_p[i] = mpas_div(pres_hyd_p[i], psfc_hyd_p[cell]);
    }
    plrad[cell] = pres2_p[top];
}

extern "C" __global__ void validate_prep_v841_f32(
    const int nlev, const int ncells, const int nedges, const int maxedges,
    const int wsm6_ready, const int prepare_winds, const int prepare_noahmp,
    const float gravity, const float rvord,
    const int *edges_on_cell, const int *n_edges_on_cell,
    const float *coeffs_reconstruct, const float *lat_cell,
    const float *lon_cell, const float *source_scalars,
    const float *source_theta_m, const float *source_exner,
    const int nspecies, const float *const *qspecies,
    const float *u_p, const float *v_p,
    const float *zz_p, const float *rho_dry, const float *rho_p,
    const float *th_p, const float *t_p, const float *pi_p,
    const float *pres_p, const float *zmid_p, const float *dz_p,
    const float *pres_hyd_p, const float *pres_hydd_p,
    const float *znu_p, const float *znu_hyd_p, const float *w_p,
    const float *z_p, const float *t2_p, const float *pres2_p,
    const float *pres2_hyd_p, const float *pres2_hydd_p,
    const float *psfc_p,
    const float *psfc_hyd_p, const float *psfc_hydd_p,
    const float *plrad, const float *noah_dz8w,
    const float *noah_qv_curr, const float *noah_t_phy,
    const float *noah_u_phy, const float *noah_v_phy,
    const float *noah_p8w, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int plane = nlev * ncells;
    const int count = n_edges_on_cell[cell];
    if (count < 0 || count > maxedges || !isfinite(lat_cell[cell])
            || !isfinite(lon_cell[cell])) atomicExch(invalid, 1);
    for (int slot = 0; slot < maxedges; ++slot) {
        const int edge = edges_on_cell[cell * maxedges + slot];
        if (slot < count) {
            if (edge < 0 || edge >= nedges) atomicExch(invalid, 1);
            const int ci = (cell * maxedges + slot) * 3;
            if (!isfinite(coeffs_reconstruct[ci])
                    || !isfinite(coeffs_reconstruct[ci + 1])
                    || !isfinite(coeffs_reconstruct[ci + 2]))
                atomicExch(invalid, 1);
        } else if (edge != -1) {
            atomicExch(invalid, 1);
        }
    }
    // The 15 non-species mass-level fields.  The species are checked from
    // qspecies, whose length is the row's, so this table no longer grows
    // with the scheme.
    const float *mass[15] = {
        u_p, v_p, zz_p,
        rho_dry, rho_p, th_p, t_p, pi_p, pres_p, zmid_p, dz_p,
        pres_hyd_p, pres_hydd_p, znu_p, znu_hyd_p};
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        if (prepare_winds && (!isfinite(u_p[i]) || !isfinite(v_p[i])))
            atomicExch(invalid, 1);
        for (int f = 2; f < 15; ++f)
            if (!isfinite(mass[f][i])) atomicExch(invalid, 1);
        for (int q = 0; q < nspecies; ++q) {
            if (!isfinite(qspecies[q][i])) atomicExch(invalid, 1);
            const float raw = source_scalars[q * plane + i];
            const float value = qspecies[q][i];
            const unsigned int expected = prep_positive_q_bits_v841(raw);
            if (!prep_finite_bits_v841(raw)
                    || __float_as_uint(value) != expected)
                atomicExch(invalid, 1);
            if ((__float_as_uint(value) & 0x80000000u) != 0u)
                atomicExch(invalid, 1);
            if (wsm6_ready && prep_negative_nonzero_bits_v841(raw))
                atomicExch(invalid, 1);
        }
        const float expected_rho = mpas_mul(
            rho_dry[i], mpas_add(1.0f, qspecies[0][i]));
        const float expected_theta = mpas_div(
            source_theta_m[i],
            mpas_add(1.0f, mpas_mul(rvord, qspecies[0][i])));
        const float expected_temp = mpas_mul(expected_theta, source_exner[i]);
        const float expected_dz = mpas_sub(z_p[i + ncells], z_p[i]);
        const float expected_zmid = mpas_mul(
            0.5f, mpas_add(z_p[i + ncells], z_p[i]));
        if (__float_as_uint(rho_p[i]) != __float_as_uint(expected_rho)
                || __float_as_uint(th_p[i]) != __float_as_uint(expected_theta)
                || __float_as_uint(t_p[i]) != __float_as_uint(expected_temp)
                || __float_as_uint(pi_p[i])
                    != __float_as_uint(source_exner[i])
                || __float_as_uint(dz_p[i]) != __float_as_uint(expected_dz)
                || __float_as_uint(zmid_p[i])
                    != __float_as_uint(expected_zmid))
            atomicExch(invalid, 1);
        if (prepare_noahmp) {
            const float expected_noah_temp = mpas_mul(
                mpas_div(
                    source_theta_m[i],
                    mpas_add(1.0f, mpas_mul(rvord, source_scalars[i]))),
                source_exner[i]);
            if (__float_as_uint(noah_qv_curr[i])
                        != __float_as_uint(source_scalars[i])
                    || __float_as_uint(noah_t_phy[i])
                        != __float_as_uint(expected_noah_temp)
                    || __float_as_uint(noah_dz8w[i])
                        != __float_as_uint(dz_p[i])
                    || __float_as_uint(noah_u_phy[i]) != __float_as_uint(u_p[i])
                    || __float_as_uint(noah_v_phy[i]) != __float_as_uint(v_p[i])
                    || __float_as_uint(noah_p8w[i])
                        != __float_as_uint(pres2_p[i]))
                atomicExch(invalid, 1);
        }
        if (rho_dry[i] <= 0.0f || rho_p[i] <= 0.0f
                || th_p[i] <= 0.0f || t_p[i] <= 0.0f
                || pi_p[i] <= 0.0f || pres_p[i] <= 0.0f
                || pres_hyd_p[i] <= 0.0f || pres_hydd_p[i] <= 0.0f
                || dz_p[i] <= 0.0f || znu_p[i] <= 0.0f
                || znu_hyd_p[i] <= 0.0f) atomicExch(invalid, 1);
        if (prepare_noahmp && (!isfinite(noah_t_phy[i]) || noah_t_phy[i] <= 0.0f
                || !isfinite(noah_p8w[i]) || noah_p8w[i] <= 0.0f))
            atomicExch(invalid, 1);
        // MPAS detects exactly this pressure inversion in MPAS_to_physics and
        // does NOT refuse.  mpas_atmphys_interface.F:458-474 tests only pres_p,
        // only across the two lowest levels
        //   :462  if(pres_p(i,1,j) .le. pres_p(i,2,j)) then
        // writes diagnostic lines at :463-472, and its single fatal escalation
        // at :473 is COMMENTED OUT in the official source:
        //   !      call mpas_log_write('pressure increasing with height', &
        //   !                          messageType=MPAS_LOG_CRIT)
        // so execution continues past :474 unconditionally.  Refusing the step
        // was stricter than the authority, and stricter at more sites: native
        // never tests pres_hyd_p or pres_hydd_p for monotonicity at all.
        // Non-finite and non-positive pressure remain refused above.
    }

    const float *interfaces[6] = {
        w_p, z_p, t2_p, pres2_p, pres2_hyd_p, pres2_hydd_p};
    for (int k = 0; k <= nlev; ++k) {
        const int i = k * ncells + cell;
        for (int f = 0; f < 6; ++f)
            if (!isfinite(interfaces[f][i])) atomicExch(invalid, 1);
        if (t2_p[i] <= 0.0f || pres2_p[i] <= 0.0f
                || pres2_hyd_p[i] <= 0.0f || pres2_hydd_p[i] <= 0.0f)
            atomicExch(invalid, 1);
        if (k < nlev) {
            const int above = i + ncells;
            // z_p ordering is RETAINED: the t2_p/fzm/fzp reconstruction below
            // divides by (z_p[k+1] - z_p[k-1]), which is native's own
            // expression at mpas_atmphys_interface.F:479
            //   tem1 = 1./(zgrid(k+1,i)-zgrid(k-1,i))
            // so a non-monotonic column is a genuine division hazard rather
            // than a state native tolerates.  The interface PRESSURE ordering
            // refusals beside it are removed for the reason cited above:
            // native has no interface pressure monotonicity test whatsoever.
            if (!(z_p[above] > z_p[i])) atomicExch(invalid, 1);
        }
    }

    for (int k = 1; k < nlev; ++k) {
        const int i = k * ncells + cell;
        const float inverse = mpas_div(
            1.0f, mpas_sub(z_p[i + ncells], z_p[i - ncells]));
        const float fzm = mpas_mul(
            mpas_sub(z_p[i], z_p[i - ncells]), inverse);
        const float fzp = mpas_mul(
            mpas_sub(z_p[i + ncells], z_p[i]), inverse);
        const float expected_t2 = mpas_add(
            mpas_mul(fzm, t_p[i]), mpas_mul(fzp, t_p[i - ncells]));
        const float expected_p2 = mpas_add(
            mpas_mul(fzm, pres_p[i]), mpas_mul(fzp, pres_p[i - ncells]));
        if (__float_as_uint(t2_p[i]) != __float_as_uint(expected_t2)
                || __float_as_uint(pres2_p[i])
                    != __float_as_uint(expected_p2))
            atomicExch(invalid, 1);
    }
    const int top = nlev * ncells + cell;
    float z0 = z_p[top];
    float z1 = mpas_mul(0.5f, mpas_add(z_p[top], z_p[top - ncells]));
    float z2 = mpas_mul(
        0.5f, mpas_add(z_p[top - ncells], z_p[top - 2 * ncells]));
    float w1 = mpas_div(mpas_sub(z0, z2), mpas_sub(z1, z2));
    float w2 = mpas_sub(1.0f, w1);
    const float expected_top_t2 = mpas_add(
        mpas_mul(w1, t_p[top - ncells]),
        mpas_mul(w2, t_p[top - 2 * ncells]));
    const float expected_top_p2 = gfk_exp_fma(mpas_add(
        mpas_mul(w1, gfk_log(pres_p[top - ncells])),
        mpas_mul(w2, gfk_log(pres_p[top - 2 * ncells]))));
    z0 = z_p[cell];
    z1 = mpas_mul(0.5f, mpas_add(z_p[cell], z_p[ncells + cell]));
    z2 = mpas_mul(
        0.5f, mpas_add(z_p[ncells + cell], z_p[2 * ncells + cell]));
    w1 = mpas_div(mpas_sub(z0, z2), mpas_sub(z1, z2));
    w2 = mpas_sub(1.0f, w1);
    const float expected_bottom_t2 = mpas_add(
        mpas_mul(w1, t_p[cell]), mpas_mul(w2, t_p[ncells + cell]));
    const float expected_bottom_p2 = mpas_add(
        mpas_mul(w1, pres_p[cell]), mpas_mul(w2, pres_p[ncells + cell]));
    if (__float_as_uint(t2_p[top]) != __float_as_uint(expected_top_t2)
            || __float_as_uint(pres2_p[top])
                != __float_as_uint(expected_top_p2)
            || __float_as_uint(t2_p[cell])
                != __float_as_uint(expected_bottom_t2)
            || __float_as_uint(pres2_p[cell])
                != __float_as_uint(expected_bottom_p2))
        atomicExch(invalid, 1);

    if (__float_as_uint(pres2_hyd_p[top])
                != __float_as_uint(pres2_p[top])
            || __float_as_uint(pres2_hydd_p[top])
                != __float_as_uint(pres2_p[top]))
        atomicExch(invalid, 1);
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = k * ncells + cell;
        const float rho_a = mpas_div(
            rho_p[i], mpas_add(1.0f, qspecies[0][i]));
        const float expected_p2_hyd = mpas_add(
            pres2_hyd_p[i + ncells],
            mpas_mul(mpas_mul(gravity, rho_p[i]), dz_p[i]));
        const float expected_p2_hydd = mpas_add(
            pres2_hydd_p[i + ncells],
            mpas_mul(mpas_mul(gravity, rho_a), dz_p[i]));
        const float expected_p_hyd = mpas_mul(
            0.5f, mpas_add(expected_p2_hyd, pres2_hyd_p[i + ncells]));
        const float expected_p_hydd = mpas_mul(
            0.5f, mpas_add(expected_p2_hydd, pres2_hydd_p[i + ncells]));
        const float expected_znu = mpas_div(pres_p[i], psfc_p[cell]);
        const float expected_znu_hyd = mpas_div(
            expected_p_hyd, psfc_hyd_p[cell]);
        if (__float_as_uint(pres2_hyd_p[i])
                    != __float_as_uint(expected_p2_hyd)
                || __float_as_uint(pres2_hydd_p[i])
                    != __float_as_uint(expected_p2_hydd)
                || __float_as_uint(pres_hyd_p[i])
                    != __float_as_uint(expected_p_hyd)
                || __float_as_uint(pres_hydd_p[i])
                    != __float_as_uint(expected_p_hydd)
                || __float_as_uint(znu_p[i])
                    != __float_as_uint(expected_znu)
                || __float_as_uint(znu_hyd_p[i])
                    != __float_as_uint(expected_znu_hyd))
            atomicExch(invalid, 1);
    }
    if (!isfinite(psfc_p[cell]) || psfc_p[cell] <= 0.0f
            || !isfinite(psfc_hyd_p[cell]) || psfc_hyd_p[cell] <= 0.0f
            || !isfinite(psfc_hydd_p[cell]) || psfc_hydd_p[cell] <= 0.0f
            || !isfinite(plrad[cell]) || plrad[cell] <= 0.0f
            || __float_as_uint(psfc_hyd_p[cell])
                != __float_as_uint(pres2_hyd_p[cell])
            || __float_as_uint(psfc_hydd_p[cell])
                != __float_as_uint(pres2_hydd_p[cell])
            || __float_as_uint(plrad[cell])
                != __float_as_uint(pres2_p[top]))
        atomicExch(invalid, 1);
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

#define GWDO_NLEV 55

extern "C" __global__ void bl_ysu_gwdo_v841_f32(
    const int nlev, const int ncells, const float dt,
    const float len_disp, const float gravity, const float cp,
    const float rd, const float fv, const float pi,
    const float *u, const float *v, const float *temperature,
    const float *qv, const float *p_mass_dry_hyd,
    const float *p_interface_dry_hyd, const float *exner,
    const float *zmid, const float *rublten_in,
    const float *rvblten_in, const float *mesh_density,
    const float *var2d, const float *oc1, const float *oa1,
    const float *oa2, const float *oa3, const float *oa4,
    const float *ol1, const float *ol2, const float *ol3,
    const float *ol4, float *rublten_out, float *rvblten_out,
    float *dtaux3d, float *dtauy3d, float *dusfcg,
    float *dvsfcg, float *rubldiff, float *rvbldiff,
    int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    if (nlev != GWDO_NLEV) {
        atomicExch(invalid, 1);
        return;
    }

    const float md = mesh_density[cell];
    bool bad = !isfinite(dt) || dt <= 0.0f || !isfinite(len_disp)
        || len_disp <= 0.0f || !isfinite(md) || md <= 0.0f || md > 1.0f
        || !isfinite(var2d[cell]) || var2d[cell] < 0.0f
        || !isfinite(oc1[cell]) || oc1[cell] < 0.0f;
    const float oa_input[4] = {oa1[cell], oa2[cell], oa3[cell], oa4[cell]};
    const float ol_input[4] = {ol1[cell], ol2[cell], ol3[cell], ol4[cell]};
    for (int j = 0; j < 4; ++j) {
        bad = bad || !isfinite(oa_input[j]) || oa_input[j] < -1.0f
            || oa_input[j] > 1.0f || !isfinite(ol_input[j])
            || ol_input[j] < 0.0f || ol_input[j] > 1.0f;
    }
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        bad = bad || !isfinite(u[i]) || !isfinite(v[i])
            || !isfinite(temperature[i]) || temperature[i] <= 0.0f
            || !isfinite(qv[i]) || qv[i] < 0.0f
            || !isfinite(p_mass_dry_hyd[i]) || p_mass_dry_hyd[i] <= 0.0f
            || !isfinite(exner[i]) || exner[i] <= 0.0f
            || !isfinite(zmid[i]) || !isfinite(rublten_in[i])
            || !isfinite(rvblten_in[i]);
        const int ii = k * ncells + cell;
        const int ii_above = (k + 1) * ncells + cell;
        bad = bad || !isfinite(p_interface_dry_hyd[ii])
            || p_interface_dry_hyd[ii] <= 0.0f;
        if (k + 1 < nlev) {
            bad = bad || !(p_mass_dry_hyd[i] > p_mass_dry_hyd[i + ncells])
                || !(zmid[i + ncells] > zmid[i]);
        }
        if (k == nlev - 1) {
            bad = bad || !isfinite(p_interface_dry_hyd[ii_above])
                || p_interface_dry_hyd[ii_above] <= 0.0f;
        }
        bad = bad || !(p_interface_dry_hyd[ii]
            > p_interface_dry_hyd[ii_above]);
    }
    if (bad) {
        atomicExch(invalid, 1);
        return;
    }

    float vtj[GWDO_NLEV];
    float vtk[GWDO_NLEV];
    float rho[GWDO_NLEV];
    float delta_p[GWDO_NLEV];
    float u1[GWDO_NLEV];
    float v1[GWDO_NLEV];
    float usqj[GWDO_NLEV];
    float bnv2[GWDO_NLEV];
    float velco[GWDO_NLEV - 1];
    float taup[GWDO_NLEV + 1];
    float taufb[GWDO_NLEV + 1];
    float taud[GWDO_NLEV];
    for (int k = 0; k < nlev; ++k) {
        usqj[k] = 0.0f;
        bnv2[k] = 0.0f;
        taud[k] = 0.0f;
    }
    for (int k = 0; k <= nlev; ++k) {
        taup[k] = 0.0f;
        taufb[k] = 0.0f;
    }

    const float dx = mpas_div(len_disp, powf(md, 0.25f));
    const float diagonal = mpas_sqrt(
        mpas_add(mpas_mul(dx, dx), mpas_mul(dx, dx)));
    const float dxy4[4] = {dx, dx, diagonal, diagonal};
    const float dxy4p[4] = {dx, dx, diagonal, diagonal};
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        const int ip = (k + 1) * ncells + cell;
        const float virtual_factor = mpas_add(1.0f, mpas_mul(fv, qv[i]));
        vtj[k] = mpas_mul(temperature[i], virtual_factor);
        vtk[k] = mpas_div(vtj[k], exner[i]);
        rho[k] = mpas_div(
            mpas_mul(mpas_div(1.0f, rd), p_mass_dry_hyd[i]), vtj[k]);
        delta_p[k] = mpas_sub(
            p_interface_dry_hyd[i], p_interface_dry_hyd[ip]);
        u1[k] = u[i];
        v1[k] = v[i];
    }

    const float zlowtop = mpas_mul(2.0f, var2d[cell]);
    int klowtop = 0;
    for (int k = 1; k < nlev; ++k) {
        const float height = mpas_sub(
            zmid[k * ncells + cell], zmid[cell]);
        if (zlowtop > 0.0f && klowtop == 0 && height >= zlowtop)
            klowtop = k + 2;
    }
    int kbl = klowtop;
    if (kbl > nlev) kbl = nlev;
    if (kbl < 2) kbl = 2;
    const float delks = mpas_div(
        1.0f, mpas_sub(p_interface_dry_hyd[cell],
            p_interface_dry_hyd[(kbl - 1) * ncells + cell]));
    const float delks1 = mpas_div(
        1.0f, mpas_sub(p_mass_dry_hyd[cell],
            p_mass_dry_hyd[(kbl - 1) * ncells + cell]));
    float ubar = 0.0f;
    float vbar = 0.0f;
    float rhobar = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        if (k + 1 < kbl) {
            const float weight = mpas_mul(delta_p[k], delks);
            ubar = mpas_add(ubar, mpas_mul(weight, u1[k]));
            vbar = mpas_add(vbar, mpas_mul(weight, v1[k]));
            rhobar = mpas_add(rhobar, mpas_mul(weight, rho[k]));
        }
    }

    const int nwdir[8] = {6, 7, 5, 8, 2, 3, 1, 4};
    const float fdir = mpas_div(8.0f, mpas_mul(2.0f, pi));
    const float wdir = mpas_add(atan2f(ubar, vbar), pi);
    const int nearest = (int)floorf(mpas_add(mpas_mul(fdir, wdir), 0.5f));
    const int nwd = nwdir[nearest % 8];
    const int direction = (nwd - 1) % 4;
    const int sign = 1 - 2 * ((nwd - 1) / 4);
    const float oa = mpas_mul((float)sign, oa_input[direction]);
    const float ol = ol_input[direction];
    const float ol_perp[4] = {
        ol_input[1], ol_input[0], ol_input[3], ol_input[2]};
    const float olp = ol_perp[direction];
    float od = mpas_div(olp, mpas_max(ol, 1.0e-5f));
    od = mpas_max(mpas_min(od, 10.0f), 0.1f);
    const float dxy = dxy4[direction];
    const float dxyp = dxy4p[direction];

    for (int k = 0; k < nlev - 1; ++k) {
        const int i = k * ncells + cell;
        const int ia = i + ncells;
        const float ti = mpas_div(
            2.0f, mpas_add(temperature[i], temperature[ia]));
        const float rdz = mpas_div(1.0f, mpas_sub(zmid[ia], zmid[i]));
        const float du = mpas_sub(u1[k], u1[k + 1]);
        const float dv = mpas_sub(v1[k], v1[k + 1]);
        const float dw2 = mpas_add(mpas_mul(du, du), mpas_mul(dv, dv));
        const float shr2 = mpas_mul(
            mpas_mul(mpas_max(dw2, 1.0f), rdz), rdz);
        const float stability = mpas_add(
            mpas_div(gravity, cp), mpas_mul(rdz, mpas_sub(vtj[k + 1], vtj[k])));
        const float bvf2 = mpas_mul(mpas_mul(gravity, stability), ti);
        usqj[k] = mpas_max(mpas_div(bvf2, shr2), -100.0f);
        bnv2[k] = mpas_div(
            mpas_mul(mpas_mul(mpas_mul(2.0f, gravity), rdz),
                mpas_sub(vtk[k + 1], vtk[k])),
            mpas_add(vtk[k + 1], vtk[k]));
    }

    float ulow = mpas_sqrt(mpas_add(mpas_mul(ubar, ubar), mpas_mul(vbar, vbar)));
    ulow = mpas_max(ulow, 1.0f);
    const float rulow = mpas_div(1.0f, ulow);
    for (int k = 0; k < nlev - 1; ++k) {
        float aligned = mpas_add(
            mpas_mul(mpas_add(u1[k], u1[k + 1]), ubar),
            mpas_mul(mpas_add(v1[k], v1[k + 1]), vbar));
        velco[k] = mpas_mul(mpas_mul(0.5f, aligned), rulow);
        if (velco[k] < 1.0f && velco[k] > 0.0f) velco[k] = 1.0f;
    }
    bool ldrag = velco[0] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl && velco[kf - 1] <= 0.0f) ldrag = true;
    }

    const float first_weight = mpas_mul(
        mpas_sub(p_mass_dry_hyd[cell], p_mass_dry_hyd[ncells + cell]),
        delks1);
    bnv2[0] = mpas_mul(first_weight, bnv2[0]);
    usqj[0] = mpas_mul(first_weight, usqj[0]);
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) {
            const int k = kf - 1;
            const float pressure_weight = mpas_mul(
                mpas_sub(p_mass_dry_hyd[k * ncells + cell],
                    p_mass_dry_hyd[(k + 1) * ncells + cell]), delks1);
            bnv2[0] = mpas_add(bnv2[0], mpas_mul(bnv2[k], pressure_weight));
            usqj[0] = mpas_add(usqj[0], mpas_mul(usqj[k], pressure_weight));
        }
    }
    ldrag = ldrag || bnv2[0] <= 0.0f || ulow == 1.0f || var2d[cell] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) usqj[kf - 1] = usqj[0];
    }

    float bnv = 0.0f;
    float fr = 0.0f;
    float xn = 0.0f;
    float yn = 0.0f;
    if (!ldrag) {
        bnv = mpas_sqrt(bnv2[0]);
        fr = mpas_mul(mpas_mul(mpas_mul(bnv, rulow), var2d[cell]), od);
        fr = mpas_min(fr, 10.0f);
        xn = mpas_mul(ubar, rulow);
        yn = mpas_mul(vbar, rulow);
    }

    float coefm = 0.0f;
    float taub = 0.0f;
    if (!ldrag) {
        float efact = powf(mpas_add(oa, 2.0f), mpas_mul(0.8f, fr));
        efact = mpas_min(mpas_max(efact, 0.0f), 10.0f);
        coefm = powf(mpas_add(1.0f, ol), mpas_add(oa, 1.0f));
        const float xlinv = mpas_div(coefm, dx);
        const float tem = mpas_mul(mpas_mul(fr, fr), oc1[cell]);
        const float gfobnv = mpas_div(
            tem, mpas_mul(mpas_add(tem, 0.5f), bnv));
        taub = mpas_mul(xlinv, rhobar);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(mpas_mul(taub, gfobnv), efact);
    }
    for (int kf = 1; kf <= nlev; ++kf) {
        if (kf <= kbl) taup[kf - 1] = taub;
    }

    bool icrilv = false;
    for (int kf = 2; kf < nlev; ++kf) {
        const int k = kf - 1;
        const int kp1 = k + 1;
        float brvf = 0.0f;
        if (kf >= kbl) {
            icrilv = icrilv || usqj[k] < 0.25f || velco[k] <= 0.0f;
            brvf = mpas_sqrt(mpas_max(bnv2[k], 1.0e-5f));
        }
        if (kf >= kbl && !ldrag && !icrilv && taup[k] > 0.0f) {
            const float temv = mpas_div(1.0f, velco[k]);
            float tem1 = mpas_div(coefm, dxy);
            tem1 = mpas_mul(tem1, mpas_add(rho[kp1], rho[k]));
            tem1 = mpas_mul(tem1, brvf);
            tem1 = mpas_mul(tem1, velco[k]);
            tem1 = mpas_mul(tem1, 0.5f);
            float hd = mpas_sqrt(mpas_div(taup[k], tem1));
            const float fro = mpas_mul(mpas_mul(brvf, hd), temv);
            const float tem2 = mpas_sqrt(usqj[k]);
            const float tem = mpas_add(1.0f, mpas_mul(tem2, fro));
            const float rim = mpas_div(
                mpas_mul(usqj[k], mpas_sub(1.0f, fro)), mpas_mul(tem, tem));
            if (rim <= 0.25f) {
                const float temc = mpas_add(2.0f, mpas_div(1.0f, tem2));
                hd = mpas_div(
                    mpas_mul(velco[k],
                        mpas_sub(mpas_mul(2.0f, mpas_sqrt(temc)), temc)),
                    brvf);
                taup[kp1] = mpas_mul(tem1, mpas_mul(hd, hd));
            } else {
                taup[kp1] = taup[k];
            }
        }
    }

    if (!ldrag) {
        int kblk = 0;
        float fbdpe = 0.0f;
        float zblk = 0.0f;
        for (int kf = nlev; kf >= 2; --kf) {
            if (kblk == 0 && kf <= kbl) {
                const int k = kf - 1;
                float contribution = mpas_mul(
                    bnv2[k], mpas_sub(zmid[(kbl - 1) * ncells + cell],
                        zmid[k * ncells + cell]));
                contribution = mpas_mul(contribution, delta_p[k]);
                contribution = mpas_div(contribution, gravity);
                contribution = mpas_div(contribution, rho[k]);
                fbdpe = mpas_add(fbdpe, contribution);
                const float fbdke = mpas_mul(0.5f,
                    mpas_add(mpas_mul(u1[k], u1[k]), mpas_mul(v1[k], v1[k])));
                if (fbdpe >= fbdke) {
                    kblk = kf < kbl ? kf : kbl;
                    zblk = mpas_sub(zmid[(kblk - 1) * ncells + cell], zmid[cell]);
                }
            }
        }
        if (kblk != 0) {
            const float fbdcd = mpas_max(
                mpas_sub(2.0f, mpas_div(1.0f, od)), 0.0f);
            float value = mpas_mul(0.5f, rhobar);
            value = mpas_mul(value, coefm);
            value = mpas_div(value, mpas_mul(dx, dx));
            value = mpas_mul(value, fbdcd);
            value = mpas_mul(value, dxyp);
            value = mpas_mul(value, olp);
            value = mpas_mul(value, zblk);
            value = mpas_mul(value, mpas_mul(ulow, ulow));
            taufb[0] = value;
            const float tautem = mpas_div(taufb[0], (float)(kblk - 1));
            for (int kf = 2; kf <= kblk; ++kf)
                taufb[kf - 1] = mpas_sub(taufb[kf - 2], tautem);
            for (int k = 0; k <= nlev; ++k)
                taup[k] = mpas_add(taup[k], taufb[k]);
        }
    }

    for (int k = 0; k < nlev; ++k) {
        taud[k] = mpas_div(
            mpas_mul(mpas_sub(taup[k + 1], taup[k]), gravity), delta_p[k]);
    }
    float dtfac = 1.0f;
    for (int kf = 1; kf < nlev; ++kf) {
        const int k = kf - 1;
        if (kf <= kbl && taud[k] != 0.0f) {
            const float limiter = mpas_abs(
                mpas_div(velco[k], mpas_mul(dt, taud[k])));
            dtfac = mpas_min(dtfac, limiter);
        }
    }

    float surface_u = 0.0f;
    float surface_v = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        taud[k] = mpas_mul(taud[k], dtfac);
        const float du = mpas_mul(taud[k], xn);
        const float dv = mpas_mul(taud[k], yn);
        dtaux3d[i] = du;
        dtauy3d[i] = dv;
        surface_u = mpas_add(surface_u, mpas_mul(du, delta_p[k]));
        surface_v = mpas_add(surface_v, mpas_mul(dv, delta_p[k]));
        rublten_out[i] = mpas_add(rublten_in[i], du);
        rvblten_out[i] = mpas_add(rvblten_in[i], dv);
        rubldiff[i] = mpas_sub(rublten_out[i], rublten_in[i]);
        rvbldiff[i] = mpas_sub(rvblten_out[i], rvblten_in[i]);
        if (!isfinite(du) || !isfinite(dv) || !isfinite(rublten_out[i])
                || !isfinite(rvblten_out[i]) || !isfinite(rubldiff[i])
                || !isfinite(rvbldiff[i])) bad = true;
    }
    dusfcg[cell] = mpas_mul(mpas_div(-1.0f, gravity), surface_u);
    dvsfcg[cell] = mpas_mul(mpas_div(-1.0f, gravity), surface_v);
    if (!isfinite(dusfcg[cell]) || !isfinite(dvsfcg[cell]) || bad)
        atomicExch(invalid, 1);
}

