 xi=((xi&0xffffffU)|0x800000U)<<shift;
 gt_u64 r0=(gt_u32)(xi*arr[0]);
 gt_u64 r1=(gt_u64)xi*arr[4], r2=(gt_u64)xi*arr[8];
 r0=((r2>>32)|(r0<<32))+r1;
 gt_u64 n=(r0+(1ULL<<61))>>62;
 r0-=n<<62;
 *np=(int)n;
 return __dmul_rn((double)(gt_i64)r0,0x1.921FB54442D18p-62);
}
