 if (top<0x398U) return cosine ? 1.0f : y;
 double x=(double)y;
 const gt_sincos_t* p=&gt_sincos_table[0];
 int n=0, sign=0;
 if (top>=0x3f4U) {
  if (top<0x42fU) {
   double r=__dmul_rn(x,p->hpi_inv);
   n=((int)r+0x800000)>>24;
   x=__fma_rn(-(double)n,p->hpi,x);
  } else {
