        break;
    }
    case 22: {
        int ig = iw - 54;
        RswSpec s = rsw_spec(colh2o[L], colo2[L],
                             MU(1.6f, RSW_C_KG22_STRRAT), 8.0f,
                             fac00[L], fac01[L], fac10[L], fac11[L]);
        const real* sf = tab + RSW_T_KG22_SFLUXREF;    // (2, 9)
        real a = sf[ig + 2 * (s.js - 1)], b = sf[ig + 2 * s.js];
