__device__ R col_depth_max(const float* values,const float* z,R bot,R top,int n) {
    int kb=0,kt=0;
    for(int k=0;k<n;k++) {if(R(z[k])<=bot) kb=k;if(R(z[k])>=top) kt=k;}
