    int k22 = *k22_io;
    float hkb = *hkb_io;
    int start_level = k22;
    kbcon = k22 + 1;
    if (iloop == 5) kbcon = k22;
    gfd_kbcon_fill_hcot(hcot, start_level, hkb, kbmax, nz, z_cup, entr_rate,
                        heo);
