        float hetest = hcot[kbcon];
        if (hetest < hes_cup[kbcon]) {
            kbcon += 1;
            if (kbcon > kbmax + 2) { *ierr_io = 3; break; }
            continue;
        }
        if (kbcon - k22 == 1) break;
        if (iloop == 5 && (kbcon - k22) <= 2) break;
