        upme[k - 1] = FADD(FSUB(zuo[k], zuo[k - 1]), upmd[k - 1]);
        if (upme[k - 1] < K_ZERO) {
            upme[k - 1] = K_ZERO;
            upmd[k - 1] = FSUB(zuo[k - 1], zuo[k]);
            if (zuo[k - 1] > K_ZERO)
                cd[k - 1] = FDIV(upmd[k - 1], FMUL(dz, zuo[k - 1]));
        }
        if (zuo[k - 1] > K_ZERO)
            entr_rate_2d[k - 1] = FDIV(upme[k - 1], FMUL(dz, zuo[k - 1]));
