    LEV_cupclw, LEV_cnvwt,
    LEV_dellu, LEV_dellv, LEV_dellah, LEV_dellaq, LEV_dellaqc, LEV_dellat,
    LEV_xhe, LEV_xq, LEV_xt, LEV_xqes, LEV_xhes,
    LEV_xqes_cup, LEV_xq_cup, LEV_xhe_cup, LEV_xhes_cup, LEV_gamma_cupx,
