        int xx=(x+dx+nx)%nx,yy=(y+dy+ny)%ny,j=yy*nx+xx;
        seen=fmaxf(seen,oldmask[j]); longest=fmaxf(longest,olddur[j]);
    }
    if(seen==1.f) dur[c]=longest+dt;
}
extern "C" __global__ void hailcast_columns(
    float* t,float* z,float* p,float* rho,float* qv,
    float* qi,float* qc,float* qr,float* qs,float* qg,float* w,
    const float* ht,const float* dur,float* e1,float* e2,float* e3,float* e4,float* e5,
    float* maximum,float* mean,float* sd,float* runmax,
    int nx,int ny,int nz) {
    int c=blockDim.x*blockIdx.x+threadIdx.x,n=nx*ny;
    if(c>=n||dur[c]<=900.f) return;
    HailArray<float> ta{t+c,n},za{z+c,n},pa{p+c,n},ra{rho+c,n},
        va{qv+c,n},ia{qi+c,n},ca{qc+c,n},raina{qr+c,n},
        sa{qs+c,n},ga{qg+c,n},wa{w+c,n};
    float h=ht[c],duration=dur[c],d[5]={0,0,0,0,0};
    HailColumn<256> column;
    column.hailstone_driver(ta,za,h,pa,ra,va,ia,ca,raina,sa,ga,wa,
        duration,nz,d[0],d[1],d[2],d[3],d[4]);
    float* embryos[5]={e1,e2,e3,e4,e5};
    // Invalid integration must remain visible to history/verification. Never
    // turn a failed stone trajectory into a plausible no-hail observation.
    if(!isfinite(runmax[c])) return;
    for(int j=0;j<5;j++) if(!isfinite(d[j])) {
        maximum[c]=mean[c]=sd[c]=runmax[c]=nanf("");
        embryos[j][c]=nanf("");return;
    }
    float m=0,mx=0,s=0;
    for(int j=0;j<5;j++) {
        float value=fmaxf(d[j],0.f);
        embryos[j][c]=fmaxf(embryos[j][c],value);
        m+=embryos[j][c]*.2f; mx=fmaxf(mx,embryos[j][c]);
    }
    for(int j=0;j<5;j++) { float e=embryos[j][c]-m; s+=e*e; }
    maximum[c]=mx; mean[c]=m; sd[c]=sqrtf(s*.25f); runmax[c]=fmaxf(runmax[c],mx);
}
// N*Q(alpha+1,lambda*D) = 0.0005 m^-3, WRF HAILMAXD criterion.
// Closed forms cover the default exponential graupel and alpha=1 hail.
__device__ double hail_tail(double a,double x) {
    if(x<=0) return 1;
    if(a==1) return exp(-x);
    if(a==2) return exp(-x)*(1+x);
    double logterm=a*log(x)-x-lgamma(a);
    if(x<a+1) {
        double term=1/a,sum=term;
        for(int j=1;j<=160;j++) { term*=x/(a+j);sum+=term;if(fabs(term)<fabs(sum)*1.e-13) break; }
        return fmax(0.,1-sum*exp(logterm));
    }
    double b=x+1-a,c=1.e300,d=1/b,h=d;
    for(int j=1;j<=160;j++) {
        double an=-j*(j-a); b+=2;
        d=an*d+b;if(fabs(d)<1.e-300)d=1.e-300;
        c=b+an/c;if(fabs(c)<1.e-300)c=1.e-300;
        d=1/d;double delta=d*c;h*=delta;if(fabs(delta-1)<1.e-13)break;
    }
    return fmax(0.,h*exp(logterm));
}
__device__ float hail_psd_size(double mass,double number,double density,double alpha) {
    if(!(mass>1.e-6&&number>0.0005&&density>0&&alpha>-1)) return 0;
    double lambda=cbrt(3.141592653589793/6*density*(alpha+1)*(alpha+2)*(alpha+3)*number/mass);
    double target=.0005/number,lo=0,hi=fmax(64.,alpha*4+64);
    if(alpha==0) return (float)(-log(target)/lambda);
    for(int j=0;j<40;j++) {
        double mid=.5*(lo+hi);
        if(hail_tail(alpha+1,mid)>target)lo=mid;else hi=mid;
    }
    return (float)(.5*(lo+hi)/lambda);
}
extern "C" __global__ void hail_psd(
    const float* rho,const float* qg,const float* ng,const float* vg,
    const float* qh,const float* nh,const float* vh,
    float* lowest,float* column,float* runlowest,float* runcolumn,
    int nx,int ny,int nz,int number_g,int volume_g,int number_h,int volume_h,
    int thompson,float density_g,float density_h,float alpha_g,float alpha_h,float intercept,float intercept_h) {
    int c=blockDim.x*blockIdx.x+threadIdx.x,n=nx*ny;
    if(c>=n) return;
    float mx=0,low=0;
    for(int k=0;k<nz;k++) {
        int i=k*n+c;
        double m=fmaxf(qg[i],0.f)*rho[i];
        double density=volume_g&&vg[i]>0?qg[i]/vg[i]:density_g;
        double number=number_g?fmaxf(ng[i],0.f)*rho[i]:0;
        if(!number_g&&m>1.e-6) {
            double n0=intercept;
            if(thompson) {
                float lg=log10f(fmaxf(1.e-9f,(float)m));
                float exponent=fmaxf(2.f,fminf(6.f,3.f+2.f/hex_divisor_40e00000*(lg+8.f)));
                n0=powf(10.f,exponent);
            }
            double lambda=pow(n0*3.141592653589793*density/m,.25);
            number=n0/lambda;
        }
        float size=hail_psd_size(m,number,density,alpha_g);
        if(number_h || intercept_h>0) {
            double mh=fmaxf(qh[i],0.f)*rho[i];
            double dh=volume_h&&vh[i]>0?qh[i]/vh[i]:density_h;
            double number=number_h?fmaxf(nh[i],0.f)*rho[i]:0;
            if(!number_h && mh>1.e-6) {
                double lambda=pow(intercept_h*3.141592653589793*dh/mh,.25);
                number=intercept_h/lambda;
            }
            size=fmaxf(size,hail_psd_size(mh,number,dh,alpha_h));
        }
        mx=fmaxf(mx,size);
        if(k==0)low=size;
    }
    lowest[c]=fmaxf(lowest[c],low);
    column[c]=fmaxf(column[c],mx);
    runlowest[c]=fmaxf(runlowest[c],low);runcolumn[c]=fmaxf(runcolumn[c],mx);
}

#include <cupy/complex.cuh>
#include <cupy/carray.cuh>
#include <cupy/atomics.cuh>
#include <cupy/math_constants.h>

#include <cub/block/block_reduce.cuh>
#include <cub/block/block_load.cuh>

typedef bool type_in0_raw;
typedef bool type_out0_raw;
typedef int IndexT;
typedef int sizeT;



typedef bool _type_reduce;

static_assert(sizeof(_type_reduce) <= 32,
    "The intermediate reduction type is assumed to be at most 32 bytes.");

// Compile-time constants for CUB template specializations
#define ITEMS_PER_THREAD  4
#define BLOCK_SIZE        64

// for hipCUB: use the hipcub namespace
#ifdef __HIP_DEVICE_COMPILE__
#define cub hipcub
#endif

#if defined FIRST_PASS
    typedef type_in0_raw  type_mid_in;
    typedef _type_reduce  type_mid_out;
    #define POST_MAP(a)   out0 = a;
#elif defined SECOND_PASS
    typedef _type_reduce  type_mid_in;
    typedef type_out0_raw type_mid_out;
    #define POST_MAP(a)   (out0 = a)
#else  // one-pass reduction
    typedef type_in0_raw  type_mid_in;
    typedef type_out0_raw type_mid_out;
    #define POST_MAP(a)   (out0 = a)
#endif

struct _reduction_op {
    __device__ __forceinline__ _type_reduce operator()(
        const _type_reduce &a, const _type_reduce &b) const {
        return a | b;
    }
};

extern "C"
__global__ void cupy_cub_any_pass2(const void* _raw_in0, void* _raw_out0, const int _segment_size, const int _array_size) {
  unsigned int _tid = threadIdx.x;

  // Specialize BlockLoad type for faster (?) loading
  typedef cub::BlockLoad<_type_reduce, BLOCK_SIZE,
                         ITEMS_PER_THREAD, cub::BLOCK_LOAD_DIRECT> BlockLoadT;

  // Shared memory for loading
  __shared__ typename BlockLoadT::TempStorage temp_storage_load;

  // Specialize BlockReduce type for our thread block
  typedef cub::BlockReduce<_type_reduce, BLOCK_SIZE> BlockReduceT;

  // Shared memory for reduction
  __shared__ typename BlockReduceT::TempStorage temp_storage;

  // Declare reduction operation
  _reduction_op op;

  // input & output raw pointers
  const type_mid_in* _in0 = static_cast<const type_mid_in*>(_raw_in0);
  type_mid_out* _out0 = static_cast<type_mid_out*>(_raw_out0);

  // Per-thread tile data
  _type_reduce _sdata[ITEMS_PER_THREAD];
  #pragma unroll
  for (int j = 0; j < ITEMS_PER_THREAD; j++) {
      _sdata[j] = _type_reduce(false);
  }

  // each block handles the reduction of 1 segment
  size_t segment_idx = size_t(blockIdx.x) * _segment_size;
  const type_mid_in* segment_head = _in0 + segment_idx;
  size_t i = 0;  // tile head within the segment
  int tile_size = (BLOCK_SIZE * ITEMS_PER_THREAD < _segment_size ?
                   BLOCK_SIZE * ITEMS_PER_THREAD :
                   _segment_size);
  sizeT _seg_size = _segment_size;

  #if defined FIRST_PASS
  // for two-pass reduction only: "last segment" is special
  if (_array_size > 0) {
      if (_array_size - segment_idx <= _segment_size) {
          _seg_size = _array_size - segment_idx;
      }
      #ifdef __HIP_DEVICE_COMPILE__
      // We don't understand HIP...
      __syncthreads();  // Propagate the new value back to memory
      #endif
  }
  #endif

  // loop over tiles within 1 segment
  _type_reduce aggregate = _type_reduce(false);
  for (i = 0; i < _seg_size; i += BLOCK_SIZE * ITEMS_PER_THREAD) {
      // for the last tile
      if (_seg_size - i <= tile_size) { tile_size = _seg_size - i; }

      // load a tile
      BlockLoadT(temp_storage_load).Load(segment_head + i, _sdata, tile_size,
                                         _type_reduce(false));

      // Compute block reduction
      // Note that the output is only meaningful for thread 0
      aggregate = op(aggregate, BlockReduceT(temp_storage).Reduce(_sdata, op));

      __syncthreads();  // for reusing temp_storage
  }

  if (_tid == 0) {
      type_mid_out& out0 = *(_out0 + blockIdx.x);
      POST_MAP(aggregate);
  }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

template <typename T> __device__ __forceinline__ T mp_pow(T x, T y);
template <> __device__ __forceinline__ float mp_pow<float>(float x, float y) { return powf(x, y); }
template <> __device__ __forceinline__ double mp_pow<double>(double x, double y) { return pow(x, y); }
template <typename T> __device__ __forceinline__ T mp_add(T x, T y) { return x + y; }
template <> __device__ __forceinline__ float mp_add<float>(float x, float y) { return mpas_add(x, y); }
template <typename T> __device__ __forceinline__ T mp_mul(T x, T y) { return x * y; }
template <> __device__ __forceinline__ float mp_mul<float>(float x, float y) { return mpas_mul(x, y); }
template <typename T> __device__ __forceinline__ T mp_div(T x, T y) { return x / y; }
template <> __device__ __forceinline__ float mp_div<float>(float x, float y) { return mpas_div(x, y); }
template <typename T> __device__ __forceinline__ T mp_sign(T x);
template <> __device__ __forceinline__ float mp_sign<float>(float x) { return mpas_copysign(1.0f, x); }
template <> __device__ __forceinline__ double mp_sign<double>(double x) { return copysign(1.0, x); }

template <typename T>
__device__ __forceinline__ void pressure_point(
    const T rho, const T rtheta, const T rho_base, const T rtheta_base,
    const T exner_base, const T zz, const T rgas, const T cp, const T p0,
    T &theta, T &exner, T &pressure, T &rho_p, T &rtheta_p, T &pressure_p) {
  theta = rtheta / rho;
  const T argument = zz * (rgas / p0) * rtheta;
  exner = mp_pow<T>(argument, rgas / (cp - rgas));
  pressure = zz * rgas * rtheta * exner;
  rho_p = rho - rho_base;
  rtheta_p = rtheta - rtheta_base;
  pressure_p = zz * rgas * (
      exner * rtheta_p + rtheta_base * (exner - exner_base));
}

/* Every kernel here walks a flat (level, owner) element index, owner
   fastest, in a grid-stride loop; each element runs the former per-owner
   loop body for its level unchanged (the terrain w column keeps its
   ascending edge-slot accumulation per level), so the launch geometry is
   not in the arithmetic.  recover_state launches one thread per element. */
#define RECOVERY_ELEMENT_LOOP(total) \
    for (int element = blockDim.x * blockIdx.x + threadIdx.x; \
         element < (total); element += gridDim.x * blockDim.x)

#define DECLARE_PRESSURE_KERNEL(NAME, T) \
extern "C" __global__ void NAME( \
    const T* rho, const T* rtheta, const T* rho_base, const T* rtheta_base, \
    const T* exner_base, const T* zz, T* theta, T* exner, T* pressure, \
    T* rho_p, T* rtheta_p, T* pressure_p, T rgas, T cp, T p0, \
    int nlev, int ncells) { \
  RECOVERY_ELEMENT_LOOP(nlev * ncells) { \
    const int index = element; \
    pressure_point<T>( \
        rho[index], rtheta[index], rho_base[index], rtheta_base[index], \
        exner_base[index], zz[index], rgas, cp, p0, theta[index], exner[index], \
        pressure[index], rho_p[index], rtheta_p[index], pressure_p[index]); \
  } \
}

DECLARE_PRESSURE_KERNEL(recover_pressure_f32, float)
DECLARE_PRESSURE_KERNEL(recover_pressure_f64, double)

#define DECLARE_EDGE_KERNEL(NAME, T) \
extern "C" __global__ void NAME( \
    const T* rho, const T* ru, const int* cells_on_edge, T* u, \
    int nlev, int ncells, int nedges) { \
  RECOVERY_ELEMENT_LOOP(nlev * nedges) { \
    const int edge = element % nedges; \
    const int level = element / nedges; \
    const int index = level * nedges + edge; \
    const int cell0 = cells_on_edge[2 * edge]; \
    const int cell1 = cells_on_edge[2 * edge + 1]; \
    const T denominator = mp_add<T>( \
        rho[level * ncells + cell0], rho[level * ncells + cell1]); \
    u[index] = mp_div<T>(mp_mul<T>(T(2), ru[index]), denominator); \
  } \
}

DECLARE_EDGE_KERNEL(recover_edge_velocity_f32, float)
DECLARE_EDGE_KERNEL(recover_edge_velocity_f64, double)

#define DECLARE_FLAT_W_KERNEL(NAME, T) \
extern "C" __global__ void NAME( \
    const T* rho, const T* rw, const T* zz, const T* fzm, const T* fzp, \
    T* w, int nlev, int ncells) { \
  RECOVERY_ELEMENT_LOOP((nlev + 1) * ncells) { \
    const int cell = element % ncells; \
    const int level = element / ncells; \
    const int index = level * ncells + cell; \
    if (level == 0 || level == nlev) { \
      w[index] = T(0); \
    } else { \
      const T metric = mp_add<T>( \
          mp_mul<T>(fzm[level], zz[level * ncells + cell]), \
          mp_mul<T>(fzp[level], zz[(level - 1) * ncells + cell])); \
      const T density = mp_add<T>( \
          mp_mul<T>(fzm[level], rho[level * ncells + cell]), \
          mp_mul<T>(fzp[level], rho[(level - 1) * ncells + cell])); \
      w[index] = mp_div<T>(mp_div<T>(rw[index], metric), density); \
    } \
  } \
}

