    for (int k = 3; k <= kend_p3 + 3; k++) {
        sec[k] = FDIV(FSUB(first[k + 1], first[k - 1]),
                      FSUB(z_cup[k + 1], z_cup[k - 1]));
        sec[k] = fabsf(sec[k]);
