    int ix = 1;
    int k = ilev;
    while (ilev < kend_p3) {
        for (int kk = k; kk <= kend_p3 + 2; kk++) {
            if (sec[kk] < sec[kk + 1] && sec[kk] < sec[kk - 1]) {
                k_inv[ix] = kk;
                ix = IMIN(5, ix + 1);
