    int kadd = 0;
    int ken = gfd_maxloc_int(k_inv, 1, nz);
    for (int kx = 1; kx <= ken; kx++) {
        int kk = k_inv[kx + kadd];
        if (kk == 1) break;
        if (dtempdz[kk] < dtempdz[kk - 1] && dtempdz[kk] < dtempdz[kk + 1]) {
