                                       FMUL(K_HALF, ddmdu[ki])), ddmeu[ki]);
                float deno = FADD(FSUB(zdo[ki + 1],
                                       FMUL(K_HALF, ddmd[ki])), ddme[ki]);
                ucd[ki] = FDIV(
