            k = (int)__fadd_rn(__fmul_rn(invln2, x), sign == 0u ? 0.5f : -0.5f);
            real scale = (real)k;
            hi = __fsub_rn(x, __fmul_rn(scale, ln2_hi));
            lo = __fmul_rn(scale, ln2_lo);
