    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= nsolve) return;
    for (int f = 0; f < 16; ++f) {
        float value = mpas_add(acc[f][cell], mpas_mul(fluxes[f][cell], dt));
        if (ring && bucket > 0.0f && value > bucket) {
            counts[f][cell] += 1;
            value = mpas_sub(value, bucket);
        }
        acc[f][cell] = value;
    }
}

