extern "C" __global__ void cupy_any(const CArray<unsigned char, 1, 1, 1> _raw_in0, CArray<bool, 0, 1, 1> _raw_out0, CIndexer<1, 1> _in_ind, CIndexer<0, 1> _out_ind, const int _block_stride) {
