    SHS_aa0, SHS_aa1, SHS_xhkb, SHS_xaa0, SHS_xkshal,
    SHS_xff1, SHS_xff2, SHS_xff3, SHS_blqe, SHS_trash_kb, SHS_xmbmax,
    SHS_xmb, SHS_xmb_out, SHS_pre,
