    extern "C" __global__ void cupy_getitem_mask(const CArray<int, 2, 1, 1> _raw_a, const CArray<bool, 2, 0, 1> _raw_mask, const CArray<int, 2, 1, 1> _raw_mask_scanned, CArray<int, 2, 1, 1> out, CIndexer<2, 1> _ind) {
      ;
