        float dpu=FSUB(press,pin[u]),dpl=FSUB(pin[u+1],press);
        value=FDIV(FADD(FMUL(ozone[col*nl+u],dpl),
                        FMUL(ozone[col*nl+u+1],dpu)),FADD(dpl,dpu));
    }
