const unsigned int stage = _raw_stage[_in_ind.get()];
const unsigned int source = _raw_source[_in_ind.get()];
      _type_reduce _a = static_cast<_type_reduce>(old | stage | source);
      _s = REDUCE(_s, _a);
    }
    _sdata[_tid] = _s;
    __syncthreads();
    for (unsigned int _block = 512 / 2;
         _block >= _block_stride; _block >>= 1) {
      if (_tid < _block) {
        _REDUCE(_block);
      }
      __syncthreads();
    }
    if (_tid < _block_stride) {
      _s = _sdata[_tid];
    }
    if (_tid < _block_stride && _i < _out_ind.size()) {
      _out_ind.set(static_cast<ptrdiff_t>(_i));
      unsigned int &out = _raw_out[_out_ind.get()];
      POST_MAP(_s);
    }
  }
}

