    typedef double in0_type;
typedef double in1_type;
typedef double out0_type;


template <typename T>
inline __device__ T integral_power(T in0, T in1) {
    if (in1 < 0) {
        if (in0 == -1) {return (in1 & 1) ? -1 : 1;}
        else {return (in0 == 1) ? 1 : 0;}
    }
    T out0 = 1;
    while (in1 > 0) {
        if (in1 & 1) {
            out0 *= in0;
        }
        in0 *= in0;
        in1 >>= 1;
    }
    return out0;
}

template <typename T>
inline __device__ T complex_power(T in0, T in1) {
    return in1 == T(0) ? T(1): pow(in0, in1);
}

    extern "C" __global__ void cupy_power__float64_float_float64(const CArray<double, 1, 1, 1> _raw_in0, const double in1, CArray<double, 1, 1, 1> _raw_out0, CIndexer<1, 1> _ind) {
      ;
      #pragma unroll 1
      CUPY_FOR(i, _ind.size()) {
        _ind.set(i);
        const in0_type in0(_raw_in0[_ind.get()]);
out0_type out0;
out0 = pow(in0, in1)
;
_raw_out0[_ind.get()] = out0;;
      }
      ;
    }

