            qt=qv2;ql2=0.0f;qi2=0.0f;
        }
        thv2=th2*(R(1.0f)+reps*qv2)/(R(1.0f)+qv2+ql2+qi2);
        b2=g*(thv2-R(thv[k]))/R(thv[k]);
        R dz=-cpdg*R(0.5f)*(R(thv[k])+R(thv[k-1]))*(R(pi[k])-R(pi[k-1]));
        R parea;
