            cin+=narea;narea=0.0f;
        } else if(b2<R(0.0f)&&b1>R(0.0f)) {
            R frac=b1/(b1-b2);
            parea=R(0.5f)*b1*dz*frac;
            narea=-R(0.5f)*b2*dz*(R(1.0f)-frac);
