    if(x== 0x1.fffffffffff70p-1 ) return __dadd_rn(0x1.8000000000009p-23,0x1p-77);
    if(x== 0x1.390e6939cd1a6p-5 ) return __dsub_rn(0x1.8856a5d3296a4p+0,0x1p-109);
    b64u64_u w; w.f = ps;
    if((w.u^t.u)>>63)
      t.u--;
    else
      t.u++;
    pl = t.f;
  }
  return __dadd_rn(ph,pl);
}

}

