    CAPL(LEV_cupclw, cupclw);
    CAPL(LEV_cnvwt, cnvwt);

    // ---- :1121-1136 : cup_up_aa0 x2 --------------------------------------
    aa0 = gfd_cup_up_aa0(z, zu, dby, gamma_cup, t_cup, kbcon, ktop, ierr,
