    SCAB[SCA_aa0] = aa0;
    SCAB[SCA_aa1] = aa1;
    ISCB[ISCA_ierr_6] = ierr;
    int ierr6_saved = ierr;

    // ---- :1141-1203 : the diurnal-cycle closure --------------------------
    float aa1_bl = K_ZERO;
    float xf_dicycle = K_ZERO;
    float tau_ecmwf = K_ZERO;
    float tau_bl = K_ZERO;
    float umean = K_ZERO;
    float wmean = K_WMEAN;
    if (ierr == 0) {
        tau_ecmwf = FDIV(FSUB(zo_cup[ktopdby], zo_cup[kbcon]), wmean);
