                FSQRT(FMUL(K_TWO,
                    FADD(FADD(FADD(FMUL(us[1], us[1]), FMUL(vs[1], vs[1])),
                              FMUL(us[kbcon], us[kbcon])),
                         FMUL(vs[kbcon], vs[kbcon])))));
            tau_bl = FDIV(FSUB(zo_cup[kbcon], z1), umean);
        } else {
            tau_bl = FDIV(FSUB(zo_cup[ktopdby], zo_cup[kbcon]), wmean);
