    float t_star = K_T_STAR;
    aa1_bl = gfd_cup_up_aa1bl(t, tn, q, qo, dtime, zo_cup, kbcon, ierr, ktf);
    if (ierr == 0) {
        if (FSUB(zo_cup[kbcon], z1) > zo[IMIN(kte, kpbl + 1)]) {
            aa1_bl = K_ZERO;
        } else {
            aa1_bl = GMAX(K_ZERO, FMUL(FDIV(aa1_bl, t_star), tau_bl));
