    // ---- :495-611 : the in-cloud updraft ----------------------------------
    GfCol hc = GFWS_AT(gfws, 43);
    GfCol qco = GFWS_AT(gfws, 44);
    GfCol dby = GFWS_AT(gfws, 45);
    GfCol hco = GFWS_AT(gfws, 46);
    GfCol dbyo = GFWS_AT(gfws, 47);
