    SCAB[SHS_xhkb] = xhkb;
    SCAB[SHS_xaa0] = xaa0;
    SCAPL(SHL_xhc, xhc);
    SCAPL(SHL_xdby, xdby);
    SCAPL(SHL_xzu, xzu);

    // ---- :817-874 : the shallow closure and the tendencies ----------------
    float xmb = K_ZERO;
    float xmbmax = K_ZERO;
    float xkshal = K_ZERO;
    float blqe = K_ZERO;
