        for (int k = 1; k <= IMIN(kpbl, ktf - 1); k++) {
            blqe = FADD(blqe,
                FDIV(FMUL(FMUL(K_HUNDRED, dhdt[k]),
                          FSUB(po_cup[k], po_cup[k + 1])),
                     K_G));
        }
