        xff2 = GMAX(K_ZERO, FDIV(blqe, trash));
        xff2 = GMIN(xmbmax, xff2);
        xmb = FDIV(FADD(FADD(xff0, xff1), xff2), K_THREE);
        xmb = GMIN(xmbmax, xmb);
        if (ichoice > 0) {
