    }

    if (c->isnow < -1) {
        isnow_old = c->isnow;
        int mssi = 1;

        for (int i = isnow_old + 1; i <= 0; ++i) {
            if (DZSNSO(i) < DZMIN(mssi - 1)) {
                int neibor;
                if (i == c->isnow + 1) {
                    neibor = i + 1;
                } else if (i == 0) {
                    neibor = i - 1;
                } else {
                    neibor = i + 1;
                    if (FADD(DZSNSO(i - 1), DZSNSO(i)) < FADD(DZSNSO(i + 1), DZSNSO(i)))
