                if (j - 1 > c->isnow + 1) {
                    for (int k = j - 1; k >= c->isnow + 2; --k) {
                        STC(k) = STC(k - 1);
                        SNICE(k) = SNICE(k - 1);
                        SNLIQ(k) = SNLIQ(k - 1);
                        DZSNSO(k) = DZSNSO(k - 1);
