            drr = FSUB(DZ(1), SN_K_P05);
            propor = FDIV(drr, DZ(1));
            zwice = FMUL(propor, SWICE(1));
            zwliq = FMUL(propor, SWLIQ(1));
            propor = FDIV(SN_K_P05, DZ(1));
            SWICE(1) = FMUL(propor, SWICE(1));
            SWLIQ(1) = FMUL(propor, SWLIQ(1));
            DZ(1) = SN_K_P05;

