//
// -- aerosol physics --------------------------------------------------------
//  float thompson_activ_ncloud(float Tt, float Ww, float NCCN,
//                              const double* tnccn_act)
//        Tt [K], Ww [m s^-1], NCCN [m^-3] (water-friendly aerosol).
//        tnccn_act is WP-01's float64 FORTRAN-ORDER (7,9,7,5,4) device
