    for (int i = 0; i < NMP_NSOIL; ++i) smcmax[i] = x[base + i];
    real csoil = x[base + NMP_NSOIL];
    for (int i = 0; i < NMP_NSOIL; ++i)
        quartz[i] = x[base + NMP_NSOIL + 1 + i];

    real df[NMP_NLAY], hcpct[NMP_NLAY], fact[NMP_NLAY];
    for (int i = 0; i < NMP_NLAY; ++i) {
        hcpct[i] = 0.0f;                                           // :2446
        df[i] = 0.0f;                                              // :2447
        fact[i] = 0.0f;
    }

