        y[2 * NMP_NLAY + i] = snicev[i];
        y[2 * NMP_NLAY + NMP_NSNOW + i] = snliqv[i];
        y[2 * NMP_NLAY + 2 * NMP_NSNOW + i] = epore[i];
    }
}

