                    ccn_number,
#ifdef NSSL2_VARIABLE_CCCN
                    fminf(qccn_concentration, ccn_number + cloud_number));
#else
                    fminf(background_ccn, ccn_number + cloud_number));
#endif
                cloud = 0.0f;
                cloud_number = 0.0f;
            } else {
                const float old_cloud = cloud;
                vapor += evaporated;
                cloud -= evaporated;
                const float removed_number =
                    0.9f * evaporated * cloud_number / old_cloud;
                ccn_number = fmaxf(
                    ccn_number,
#ifdef NSSL2_VARIABLE_CCCN
                    fminf(qccn_concentration, ccn_number + removed_number));
#else
                    fminf(background_ccn, ccn_number + removed_number));
#endif
                cloud_number -= removed_number;
                theta -= latent_over_cp_exner * evaporated;
            }
        } else if (supersaturation_percent > 0.0f
                   && cloud > qxmin_cloud && cloud_number >= 1.0f) {
            const float dynamic_viscosity =
                1.832e-5f * (416.16f / (temperature + 120.0f))
                * powf(__fdiv_rn(temperature, 296.0f), 1.5f);
            const float thermal_conductivity =
                __fdiv_rn(2.43e-2f * dynamic_viscosity, 1.718e-5f);
            const float vapor_diffusivity =
                2.11e-5f * powf(__fdiv_rn(temperature, 273.15f), 1.94f)
                * (101325.0f / pressure);
            const float vapor_pressure =
                610.78f * nssl2_sat_table(temperature);
            const float ac1 = latent_heat * latent_heat /
                (thermal_conductivity * 461.5f
                 * temperature * temperature);
            const float bc = 461.5f * temperature /
                (vapor_diffusivity * vapor_pressure);
            const float resistance_inverse = 1.0f / (ac1 + bc);
            const float cloud_transfer = resistance_inverse
                * 4.0f * pi * 0.8929795026779175f
                * 0.5f * cloud_diameter * cloud_number / rho;

            float rain_transfer = 0.0f;
            if (rain > qxmin_rain && rain_number > 1.0e-9f) {
                const float kinematic_viscosity = dynamic_viscosity / rho;
                const float vapor_schmidt =
                    kinematic_viscosity / vapor_diffusivity;
                const float ventilation_scale =
                    powf(vapor_schmidt, 1.0f / 3.0f)
                    * powf(kinematic_viscosity, -0.5f);
                const float density_velocity = sqrtf(1.225f / rho);
                const float rain_ventilation =
                    0.78f
                    + 0.308f * 1.8273550271987915f
                        * ventilation_scale
                        * sqrtf(841.99666f * density_velocity)
                        * powf(rain_diameter, 0.9f);
                rain_transfer = resistance_inverse
                    * 4.0f * pi * rain_ventilation
                    * 0.5f * rain_diameter * rain_number / rho;
            }

            if (cloud_transfer > 0.0f && isfinite(cloud_transfer)) {
                float trial_vapor = vapor;
                float trial_saturation = saturation;
                float trial_temperature = temperature;
                float trial_ratio = trial_vapor / trial_saturation;
                float previous_ratio = trial_ratio;
                float previous_temperature = trial_temperature;
                float delta;
                if (fabsf(trial_ratio - 1.0f) > 1.0e-5f) {
                    delta = 0.5f * (trial_vapor - trial_saturation)
                        / (cloud_transfer * (trial_ratio - 1.0f));
                } else {
                    delta = 0.1f * dt;
                }
                const float dt_small = fminf(0.05f, 0.2f * delta);
                int native_steps = 2 * (int)floorf(
                    (dt - 4.0f * dt_small) / delta + 0.5f);
                if (native_steps < 5) native_steps = 5;
                const float dt_large =
                    (dt - 4.0f * dt_small) / (float)native_steps;

                int step_index = 1;
                int guard = 0;
                float elapsed = 0.0f;
                bool stop_adjustment = false;
                while (elapsed < dt && guard < 100000) {
                    ++guard;
                    float dt_condense =
                        step_index <= 4 ? dt_small : dt_large;
                    float midpoint_cloud;
                    float midpoint_rain;
                    float midpoint_temperature_change;
                    float midpoint_vapor;
                    float midpoint_saturation;
                    float midpoint_ratio;
                    while (true) {
                        midpoint_cloud =
                            -(trial_ratio - 1.0f)
                            * cloud_transfer * dt_condense;
                        midpoint_rain =
                            -(trial_ratio - 1.0f)
                            * rain_transfer * dt_condense;
                        midpoint_temperature_change =
                            -0.5f * latent_over_cp
                            * (midpoint_cloud + midpoint_rain);
                        const float midpoint_temperature =
                            trial_temperature
                            + midpoint_temperature_change;
                        const float midpoint_saturation_change =
                            midpoint_temperature_change
                            * (380.0f / pressure)
                            * nssl2_dtabqvs(midpoint_temperature);
                        midpoint_vapor = trial_vapor
                            + midpoint_cloud + midpoint_rain;
                        midpoint_saturation = trial_saturation
                            + midpoint_saturation_change;
                        midpoint_ratio =
                            midpoint_vapor / midpoint_saturation;
                        if (midpoint_ratio < 1.0f) {
                            dt_condense *= 0.5f;
                            if (dt_condense >= dt_small) continue;
                            stop_adjustment = true;
                        }
                        break;
                    }
                    if (stop_adjustment) break;

                    const float vapor_to_cloud =
                        -(midpoint_ratio - 1.0f)
                        * cloud_transfer * dt_condense;
                    const float vapor_to_rain =
                        -(midpoint_ratio - 1.0f)
                        * rain_transfer * dt_condense;
                    const float temperature_change =
                        -latent_over_cp
                        * (vapor_to_cloud + vapor_to_rain);
                    const float final_temperature =
                        trial_temperature + temperature_change;
                    const float saturation_change = temperature_change
                        * (380.0f / pressure)
                        * nssl2_dtabqvs(final_temperature);

                    trial_vapor += vapor_to_cloud + vapor_to_rain;
                    cloud_increment -= vapor_to_cloud;
                    rain_increment -= vapor_to_rain;
                    trial_saturation += saturation_change;
                    trial_ratio = trial_vapor / trial_saturation;
                    trial_temperature += temperature_change;
                    if (previous_temperature == trial_temperature
                            || previous_ratio == trial_ratio
                            || trial_ratio == 1.0f
                            || (step_index > 10
                                && trial_ratio < 1.0005f)) {
                        break;
                    }
                    previous_ratio = trial_ratio;
                    previous_temperature = trial_temperature;
                    elapsed += dt_condense;
                    ++step_index;
                }

                theta += latent_over_cp_exner
                    * (cloud_increment + rain_increment);
                vapor -= cloud_increment + rain_increment;
                cloud += cloud_increment;
                rain += rain_increment;
                temperature = theta * exner_local;
                saturation = nssl2_qvs(temperature, pressure);
            }

            // Default irenuc=2 continuation for an existing cloud.
            const int k = idx / horizontal_size;
            const float mass_level_w = 0.5f * (
                w_interface[idx] + w_interface[idx + horizontal_size]);
            bool admit_renucleation = cloud_increment > 0.0f
                && supersaturation_percent > 0.5f
                && supersaturation_percent < 238.0f
                && !(k == 0 && mass_level_w > 0.0f);
            if (admit_renucleation && k > 0 && k < nz - 2) {
                const float below_ss = initial_supersaturation_percent[
                    idx - horizontal_size];
                const float above_ss = initial_supersaturation_percent[
                    idx + horizontal_size];
                if (below_ss >= 238.0f || above_ss >= 238.0f) {
                    admit_renucleation = false;
                }
            }
            if (admit_renucleation) {
                const float nucleation_pool = predicted_ccn
                    ? fmaxf(ccn_number, background_ccn)
                    : diagnostic_cnuc;
                const float diagnosed_activated =
                    background_ccn - ccn_number;
                float activated = 23.984773635864258f
                    * powf(nucleation_pool, 0.7692307829856873f)
                    * powf(fmaxf(mass_level_w, 0.0f),
                           0.3461538553237915f);
                activated = fminf(activated, ccn_number);
                activated = fminf(
                    activated, __fdiv_rn(0.5f * cloud_increment, cloud_min_mass));
                activated = fminf(
                    activated,
                    fmaxf(0.0f, nucleation_pool - diagnosed_activated));
                activated = fmaxf(activated, 0.0f);
                cloud_number += activated;
                ccn_number = fmaxf(0.0f, ccn_number - activated);
            }
        } else if (supersaturation_percent > 0.0f) {
            // No pre-existing cloud: iqcinit=2 ordinary QVEXCESS path.
            float initial_cloud_increment = 0.0f;
            if (supersaturation_percent > 0.4f
                    && supersaturation_percent < 20.0f
                    && ccn_number > 0.05f * background_ccn) {
                initial_cloud_increment = nssl2_qvexcess(
                    theta, pressure, exner_local, vapor, cloud,
                    latent_over_cp, 0.4f);
            }
            theta += latent_over_cp_exner * initial_cloud_increment;
            vapor -= initial_cloud_increment;
            cloud += initial_cloud_increment;
            cloud_increment = initial_cloud_increment;
            temperature = theta * exner_local;
            saturation = nssl2_qvs(temperature, pressure);

            const float mass_level_w = 0.5f * (
                w_interface[idx] + w_interface[idx + horizontal_size]);
            if (initial_cloud_increment > qxmin_cloud
                    && mass_level_w > 0.0f) {
                const float activation_pool = predicted_ccn
                    ? fmaxf(ccn_number, background_ccn)
                    : diagnostic_cnuc;
                float activated = 23.984773635864258f
                    * powf(activation_pool, 0.7692307829856873f)
                    * powf(mass_level_w, 0.3461538553237915f);
                const float four_micron_mass =
                    1000.0f * (4.0f * pi / 3.0f)
                    * (4.0e-6f * 4.0e-6f * 4.0e-6f);
                activated = fminf(
                    background_ccn,
                    fmaxf(activated, __fdiv_rn(rho * cloud, four_micron_mass)));
                activated = fminf(activated, ccn_number);
                ccn_number = fmaxf(0.0f, ccn_number - activated);
                cloud_number = fmaxf(cloud_number, activated);
                cloud_number = fminf(
                    cloud_number, __fdiv_rn(rho * fmaxf(cloud, 0.0f),
                        cloud_min_mass));
            }
        }

        // Active default maxsupersat=1.9 / imaxsupopt=4 adjustment.
        temperature = theta * exner_local;
        saturation = nssl2_qvs(temperature, pressure);
        if (vapor > 1.9f * saturation) {
            const float vapor_excess = nssl2_qvexcess(
                theta, pressure, exner_local, vapor, cloud,
                latent_over_cp, 90.0f);
            if (vapor_excess > 0.0f) {
                theta += latent_over_cp_exner * vapor_excess;
                vapor -= vapor_excess;
                cloud += vapor_excess;
                const float activation_mass = fmaxf(
                    cloud_five_micron_mass,
                    fmaxf(cloud_twenty_micron_mass, cloud_mean_mass));
                float activated = fminf(
                    fmaxf(ccn_number, background_ccn),
                    rho * vapor_excess / activation_mass);
                ccn_number = fmaxf(0.0f, ccn_number - activated);
                cloud_number += activated;
            }
        }

        // Native final droplet mean-mass bound.
        if (cloud_number > cxmin && cloud > qxmin_cloud) {
            cloud_mean_mass = rho * cloud / cloud_number;
            if (cloud_mean_mass < cloud_min_mass
                    || cloud_mean_mass > cloud_max_mass) {
                cloud_mean_mass = fminf(
                    cloud_max_mass,
                    fmaxf(cloud_min_mass, cloud_mean_mass));
                cloud_number = rho * cloud / cloud_mean_mass;
            }
        }
        // NUCOND diagnoses/clamps the final rain mean volume but, in the
        // official rcond=2 source, does not scatter a reconstructed number.
        if (rain_number > 0.0f && rain > qxmin_rain) {
            rain_mean_volume = rho * rain / (1000.0f * rain_number);
            rain_mean_volume = fminf(
                rain_max_volume,
                fmaxf(rain_min_volume, rain_mean_volume));
        }
    }

    // All-domain warm-category cleanup from the tail of NUCOND.
    if (rain < qxmin_rain || rain_number <= 0.0f) {
        vapor += fmaxf(rain, 0.0f);
        rain = 0.0f;
        rain_number = 0.0f;
    }
    if (cloud <= qxmin_cloud || cloud_number <= 0.0f) {
        vapor += fmaxf(cloud, 0.0f);
        cloud = 0.0f;
        ccn_number += fmaxf(cloud_number, 0.0f);
        cloud_number = 0.0f;
        // WRF restores predicted CCN only when the cell is also free of
        // primary ice plus snow.  Omitting this frozen-water gate nudges CCN
        // in mixed-phase/anvil levels where official NUCOND leaves it alone.
        const float retained_ice =
            (qi[idx] > 1.0e-13f && qni[idx] > 0.0f) ? qi[idx] : 0.0f;
        const float retained_snow =
            (qs[idx] >= 1.0e-13f && qns[idx] > 0.0f) ? qs[idx] : 0.0f;
        if (ccn_number > 1.0f
                && retained_ice + retained_snow < 1.0e-13f) {
#ifdef NSSL2_VARIABLE_CCCN
            ccn_number = qccn_concentration
                - fmaxf(0.0f, qccn_concentration - ccn_number)
#else
            ccn_number = background_ccn
                - fmaxf(0.0f, background_ccn - ccn_number)
#endif
                    * expf(__fdiv_rn(-dt, 3600.0f));
        }
    }

    full_theta[idx] = theta;
    qv[idx] = fmaxf(vapor, 0.0f);
    qc[idx] = fmaxf(cloud, 0.0f);
    qr[idx] = fmaxf(rain, 0.0f);
    qndrop[idx] = fmaxf(cloud_number, 0.0f) * output_number_scale;
    qnr[idx] = fmaxf(rain_number, 0.0f) * output_number_scale;
    qnn[idx] = fmaxf(ccn_number, 0.0f) * output_number_scale;
}

// noahmp_vegeflux.cu -- CUDA transcription of the Noah-MP VEGE_FLUX subtree
// (WRF v4.6.1 phys/module_sf_noahmplsm.F, commit
//  d66e442fccc04111067e29274c9f9eaccc3cef28,
//  sha256 bd592a5b7db29000e715250e3a7c779ffb5e0dcc356f6b5a7d9e1c9f69c55282).
//
// Gate: max_ulp 0 against the gfortran+glibc oracle fixture
// gpuwm/data/noahmp/oracle/noahmp-vegeflux.csv.
//
// Two things make that reachable and both are load-bearing:
//
//  1. Every FP32 operation goes through __fadd_rn / __fsub_rn / __fmul_rn /
//     __fdiv_rn / __fsqrt_rn.  Those pin the *hardware* rounding mode and, just
//     as importantly, stop nvcc contracting a*b+c into an FMA that the SSE
//     baseline gfortran targets cannot emit.
//
//  2. The transcendentals are glibc 2.39's own logf/expf/powf/atanf, not CUDA's
//     device libm.  CUDA's __logf/logf/powf are different functions with
//     different error, and no amount of rounding control makes them agree.
//     glibc's kernels compute in binary64 and round once; the binary64 steps
//     here use __dadd_rn/__dsub_rn/__dmul_rn and __fma_rn, with __fma_rn used
//     at exactly the sites where the -fma multiarch build of glibc contracts
//     (read off the disassembly of the installed libm.so.6, not guessed).
//
// The coefficient tables live in __constant__ memory and are uploaded from the
// host.  They are deliberately *not* literal arrays inside the kernels: ptxas
// 12.8's constant folder does not honour round-to-nearest-even, so a literal
// FP table can have its differences mis-folded at compile time, and __fsub_rn
// pins the hardware mode, not the compiler's folder.  Uploading them means the
// compiler never sees the values.

// nvrtc has no <stdint.h>, so the fixed-width types are spelled out.  They are
// the only integer widths this file relies on and both are exact on every
// target CUDA supports.
typedef unsigned int uint32_t;
typedef int int32_t;

// ---------------------------------------------------------------------------
// rounding-pinned arithmetic
// ---------------------------------------------------------------------------
#define FA(a, b) __fadd_rn((a), (b))
#define FS(a, b) __fsub_rn((a), (b))
#define FM(a, b) __fmul_rn((a), (b))
#define FD(a, b) __fdiv_rn((a), (b))
#define FSQ(a)   __fsqrt_rn(a)

#define DA(a, b) __dadd_rn((a), (b))
#define DS(a, b) __dsub_rn((a), (b))
#define DM(a, b) __dmul_rn((a), (b))
#define DFMA(a, b, c) __fma_rn((a), (b), (c))

__device__ __forceinline__ float fmnf(float a, float b) { return a < b ? a : b; }
__device__ __forceinline__ float fmxf(float a, float b) { return a > b ? a : b; }

// gfortran's expansion of integer powers.  x**3 -> x*(x*x), x**4 -> (x*x)*(x*x).
__device__ __forceinline__ float p3f(float x) { return FM(x, FM(x, x)); }
__device__ __forceinline__ float p4f(float x) { float t = FM(x, x); return FM(t, t); }

// ---------------------------------------------------------------------------
// glibc 2.39 libm tables (uploaded from the host; never literals)
// ---------------------------------------------------------------------------
// Declared inside extern "C" so the symbol names survive unmangled and the
// host can cuModuleGetGlobal them by name to upload the values.
extern "C" {
__constant__ unsigned long long c_exp2f_tab[32];
__constant__ double c_exp2f_poly[3];         // unscaled  (powf's exp2_inline)
__constant__ double c_exp2f_poly_scaled[3];  // scaled    (expf)
__constant__ double c_exp2f_shift;           // 0x1.8p52
__constant__ double c_exp2f_shift_scaled;    // 0x1.8p52 / 32
__constant__ double c_exp2f_invln2_scaled;   // (1/ln2) * 32

__constant__ double c_logf_tab[32];          // invc, logc interleaved
__constant__ double c_logf_ln2;
__constant__ double c_logf_poly[3];

__constant__ double c_powf_tab[32];          // invc, logc interleaved
__constant__ double c_powf_poly[5];

__constant__ float c_atanhi[4];
__constant__ float c_atanlo[4];
__constant__ float c_atan_aT[11];
}

// ---------------------------------------------------------------------------
// glibc logf  (sysdeps/ieee754/flt-32/e_logf.c, __logf_fma)
// ---------------------------------------------------------------------------
__device__ float glibc_logf(float x)
{
#ifdef USE_DEVICE_LIBM
    return logf(x);   // negative control: CUDA device libm, a different function
#else
    uint32_t ix = __float_as_uint(x);
    if (ix == 0x3f800000u) return 0.0f;
    if ((ix - 0x00800000u) >= (0x7f800000u - 0x00800000u)) {
        if ((ix * 2u) == 0u) return -__int_as_float(0x7f800000);
        if (ix == 0x7f800000u) return x;
        if ((ix & 0x80000000u) || (ix * 2u) >= 0xff000000u)
            return __int_as_float(0x7fc00000);
        ix = __float_as_uint(FM(x, __int_as_float(0x4b000000)));  // x * 0x1p23
        ix -= (23u << 23);
    }

    uint32_t tmp = ix - 0x3f330000u;
    int i = (int)((tmp >> 19) & 15u);
    int k = ((int32_t)tmp) >> 23;
    uint32_t iz = ix - (tmp & 0xff800000u);
    double invc = c_logf_tab[2 * i];
    double logc = c_logf_tab[2 * i + 1];
    double z = (double)__uint_as_float(iz);

    double r = DFMA(z, invc, -1.0);
    double y0 = DFMA((double)k, c_logf_ln2, logc);

    double r2 = DM(r, r);
    double y = DFMA(c_logf_poly[1], r, c_logf_poly[2]);
    y = DFMA(c_logf_poly[0], r2, y);
    y = DFMA(r2, y, DA(y0, r));
    return (float)y;
#endif
}

// ---------------------------------------------------------------------------
// glibc expf  (sysdeps/ieee754/flt-32/e_expf.c, __expf_fma)
// ---------------------------------------------------------------------------
__device__ float glibc_expf(float x)
{
#ifdef USE_DEVICE_LIBM
    return expf(x);   // negative control
#else
    uint32_t ux = __float_as_uint(x);
    uint32_t abstop = (ux >> 20) & 0x7ffu;
    if (abstop >= 0x42bu) {
        if (ux == 0xff800000u) return 0.0f;
        if (abstop >= 0x7f8u) return FA(x, x);
        if (x > 88.72283935546875f) return __int_as_float(0x7f800000);
        if (x < -103.97207641601562f) return 0.0f;
    }

    double xd = (double)x;
    double kd = DFMA(c_exp2f_invln2_scaled, xd, c_exp2f_shift);
    unsigned long long ki = __double_as_longlong(kd);
    kd = DS(kd, c_exp2f_shift);
    double r = DFMA(c_exp2f_invln2_scaled, xd, -kd);

    unsigned long long t = c_exp2f_tab[ki & 31ull];
    t += ki << 47;
    double s = __longlong_as_double((long long)t);

    double z = DFMA(c_exp2f_poly_scaled[0], r, c_exp2f_poly_scaled[1]);
    double r2 = DM(r, r);
    double y = DFMA(r, c_exp2f_poly_scaled[2], 1.0);
    y = DFMA(z, r2, y);
    y = DM(y, s);
    return (float)y;
#endif
}

// ---------------------------------------------------------------------------
// glibc powf  (sysdeps/ieee754/flt-32/e_powf.c, __powf_fma)
// Only the finite, positive-base domain the Noah-MP leaves reach is
// transcribed; anything else returns NaN rather than a value nothing verified.
// ---------------------------------------------------------------------------
__device__ double powf_log2_inline(uint32_t ix)
{
    uint32_t tmp = ix - 0x3f330000u;
    int i = (int)((tmp >> 19) & 15u);
    uint32_t top = tmp & 0xff800000u;
    uint32_t iz = ix - top;
    int k = ((int32_t)top) >> 23;
    double invc = c_powf_tab[2 * i];
    double logc = c_powf_tab[2 * i + 1];
    double z = (double)__uint_as_float(iz);

    double r = DFMA(z, invc, -1.0);
    double y0 = DA(logc, (double)k);

    double r2 = DM(r, r);
    double y = DFMA(c_powf_poly[0], r, c_powf_poly[1]);
    double p = DFMA(c_powf_poly[2], r, c_powf_poly[3]);
    double r4 = DM(r2, r2);
    double q = DFMA(c_powf_poly[4], r, y0);
    q = DFMA(p, r2, q);
    y = DFMA(y, r4, q);
    return y;
}

__device__ double powf_exp2_inline(double xd)
{
    double kd = DA(xd, c_exp2f_shift_scaled);
    unsigned long long ki = __double_as_longlong(kd);
    kd = DS(kd, c_exp2f_shift_scaled);
    double r = DS(xd, kd);

    unsigned long long t = c_exp2f_tab[ki & 31ull];
    t += ki << 47;
    double s = __longlong_as_double((long long)t);

    double z = DFMA(c_exp2f_poly[0], r, c_exp2f_poly[1]);
    double r2 = DM(r, r);
    double y = DFMA(r, c_exp2f_poly[2], 1.0);
    y = DFMA(z, r2, y);
    return DM(y, s);
}

__device__ float glibc_powf(float x, float y)
{
#ifdef USE_DEVICE_LIBM
    return powf(x, y);   // negative control
#else
    uint32_t ix = __float_as_uint(x);
    uint32_t iy = __float_as_uint(y);

    // zeroinfnan(iy) or x subnormal/inf/nan/negative
    bool iy_special = ((2u * iy - 1u) >= (2u * 0x7f800000u - 1u));
    if ((ix - 0x00800000u) >= (0x7f800000u - 0x00800000u) || iy_special) {
        if (iy_special) {
            if ((2u * iy) == 0u) return 1.0f;
            if (ix == 0x3f800000u) return 1.0f;
        }
        return __int_as_float(0x7fc00000);   // outside the transcribed domain
    }

    double logx = powf_log2_inline(ix);
    double ylogx = DM((double)y, logx);
    unsigned long long uy = __double_as_longlong(ylogx);
    if (((uy >> 47) & 0xffffull) >= (__double_as_longlong(126.0) >> 47)) {
        if (ylogx > 127.99999995223258)  return __int_as_float(0x7f800000);
        if (ylogx <= -150.0)             return 0.0f;
    }
    return (float)powf_exp2_inline(ylogx);
#endif
}

// ---------------------------------------------------------------------------
// glibc atanf  (sysdeps/ieee754/flt-32/s_atanf.c -- plain binary32, no FMA)
// aT[0] is 0x3EAAAAAB: the decimal literal, not the stale hex comment.
// ---------------------------------------------------------------------------
__device__ float glibc_atanf(float x)
{
#ifdef USE_DEVICE_LIBM
    return atanf(x);   // negative control
#elif defined(GPUWM_NOAHMP_ATAN_GLIBC243)
    return noahmp_glibc243_atanf(x);
#else
    int32_t hx = (int32_t)__float_as_uint(x);
    int32_t ix = hx & 0x7fffffff;
    int id;

    if (ix >= 0x4c000000) {
        if (ix > 0x7f800000) return FA(x, x);
        return hx > 0 ? FA(c_atanhi[3], c_atanlo[3])
                      : FS(-c_atanhi[3], c_atanlo[3]);
    }
    if (ix < 0x3ee00000) {
        if (ix < 0x31000000) return x;
        id = -1;
    } else {
        x = fabsf(x);
        if (ix < 0x3f980000) {
            if (ix < 0x3f300000) {
                id = 0;
                x = FD(FS(FM(2.0f, x), 1.0f), FA(2.0f, x));
            } else {
                id = 1;
                x = FD(FS(x, 1.0f), FA(x, 1.0f));
            }
        } else if (ix < 0x401c0000) {
            id = 2;
            x = FD(FS(x, 1.5f), FA(1.0f, FM(1.5f, x)));
        } else {
            id = 3;
            x = FD(-1.0f, x);
        }
    }

    float z = FM(x, x);
    float w = FM(z, z);
    float s1 = FA(c_atan_aT[8], FM(w, c_atan_aT[10]));
    s1 = FA(c_atan_aT[6], FM(w, s1));
    s1 = FA(c_atan_aT[4], FM(w, s1));
    s1 = FA(c_atan_aT[2], FM(w, s1));
    s1 = FA(c_atan_aT[0], FM(w, s1));
    s1 = FM(z, s1);
    float s2 = FA(c_atan_aT[7], FM(w, c_atan_aT[9]));
    s2 = FA(c_atan_aT[5], FM(w, s2));
    s2 = FA(c_atan_aT[3], FM(w, s2));
    s2 = FA(c_atan_aT[1], FM(w, s2));
    s2 = FM(w, s2);

    if (id < 0) return FS(x, FM(x, FA(s1, s2)));
    float r = FS(c_atanhi[id], FS(FS(FM(x, FA(s1, s2)), c_atanlo[id]), x));
    return hx < 0 ? -r : r;
#endif
}

