        number_flux[nz] = 0.0f;

        surface_mean_flux += cloud[0] * velocity[0] * dt_fraction;

        for (int k = 0; k < nz; ++k) {
            const size_t idx = IDX3(k, j, i);
            const float inverse_dz = 1.0f / dz[idx];
