// ---------------------------------------------------------------------------
// Fortran intrinsic helpers
// ---------------------------------------------------------------------------
TEMPO_HD float tmax(float a, float b) { return a > b ? a : b; }
TEMPO_HD float tmin(float a, float b) { return a < b ? a : b; }
TEMPO_HD float tmax3(float a, float b, float c) { return tmax(tmax(a, b), c); }
TEMPO_HD float tmin3(float a, float b, float c) { return tmin(tmin(a, b), c); }
TEMPO_HD int imax(int a, int b) { return a > b ? a : b; }
TEMPO_HD int imin(int a, int b) { return a < b ? a : b; }
// Fortran NINT: nearest integer, halfway cases away from zero (gfortran calls
// lround).  x - trunc(x) is exact, so the halfway test sees x itself.  The
// earlier floor(x + 0.5f) rounded 0.49999999999999994f up to 1 because x + 0.5f
// rounds to 1.0f before the floor; graupel at the 50 kg m-3 density bound
// computes exactly that ratio in the density index nint(10 rg / rb) and took
// the next density class (tools/tempo_ref/oracle, tests/test_tempo_nint.py).
TEMPO_HD int tnint(float x) {
  float t = trunc(x);
  float f = x - t;
  if (f >= 0.5f) t += 1.0f;
  else if (f <= -0.5f) t -= 1.0f;
  return (int)t;
}
// Fortran SIGN(a, b)
TEMPO_HD float tsign(float a, float b) { return copysign(fabs(a), b); }
// libgcc __powidf2 order for real ** integer
TEMPO_HD float tpowi(float x, int m) {
  unsigned int n = m < 0 ? (unsigned int)(-m) : (unsigned int)m;
  float y = (n % 2) ? x : 1.0f;
  while (n >>= 1) {
    x = x * x;
    if (n % 2) y = y * x;
  }
  return m < 0 ? 1.0f / y : y;
}

// ---------------------------------------------------------------------------
// module_mp_tempo_utils (column-callable parts)
// ---------------------------------------------------------------------------
TEMPO_HD float calc_rslf(float p, float t) {
  const float c0 = .611583699E03f, c1 = .444606896E02f, c2 = .143177157e01f;
  const float c3 = .264224321e-1f, c4 = .299291081e-3f, c5 = .203154182e-5f;
  const float c6 = .702620698e-8f, c7 = .379534310e-11f, c8 = -.321582393e-13f;
  float x = tmax(-80.0f, t - 273.16f);
  float esl = c0 + x * (c1 + x * (c2 + x * (c3 + x * (c4 + x * (c5 + x * (c6 + x * (c7 + x * c8)))))));
  esl = tmin(esl, p * 0.15f);
  return .622f * esl / (p - esl);
}

TEMPO_HD float calc_rsif(float p, float t) {
  const float c0 = .609868993e03f, c1 = .499320233e02f, c2 = .184672631e01f;
  const float c3 = .402737184e-1f, c4 = .565392987e-3f, c5 = .521693933e-5f;
  const float c6 = .307839583e-7f, c7 = .105785160e-9f, c8 = .161444444e-12f;
  float x = tmax(-80.0f, t - 273.16f);
  float esi = c0 + x * (c1 + x * (c2 + x * (c3 + x * (c4 + x * (c5 + x * (c6 + x * (c7 + x * c8)))))));
  esi = tmin(esi, p * 0.15f);
  return .622f * esi / tmax(1.e-4f, (p - esi));
}

TEMPO_HD int get_nuc(const TempoParams& P, float nc) {
  if ((PS(nu_c_scale) / nc) >= 12.5f) return 15;
  return imin(15, tnint(PS(nu_c_scale) / nc) + 2);
}

TEMPO_HD float calc_gamma_series(float a, float x) {
  const int it_max = 100;
  const float smallvalue = 1.e-7f;
  float ap1 = a;
  float sum_term = 1.0f / tgamma(ap1 + 1.0f);
  float sum = sum_term;
  for (int k = 1; k <= it_max; ++k) {
    ap1 = ap1 + 1.0f;
    sum_term = sum_term * x / ap1;
    sum = sum + sum_term;
    if (fabs(sum_term) < (fabs(sum) * smallvalue)) break;
  }
  return sum * tempo_pow(x, a) * tempo_exp(-x);
}

TEMPO_HD float calc_gamma_cf(float a, float x) {
  const int it_max = 100;
  const float smallvalue = 1.e-7f;
  const float offset = 1.e-30f;
  float b = 1.0f - a + x;
  float d = 1.0f / b;
  float h0 = offset;
  float c = b + (1.0f / offset);
  float delta = c * d;
  float h = h0 * delta;
  for (int k = 1; k <= it_max; ++k) {
    float aj = k * (a - k);
    b = b + 2.0f;
    d = b + aj * d;
    if (fabs(d) < offset) d = offset;
    c = b + aj / c;
    if (fabs(c) < offset) c = offset;
    d = 1.0f / d;
    delta = c * d;
    h = h * delta;
    if (fabs(delta - 1.0f) < smallvalue) break;
  }
  return tempo_exp(-x + a * tempo_log(x)) * h / tgamma(a);
}

TEMPO_HD float calc_gamma_p(float a, float x) {
  if (x < (a + 1.0f)) return calc_gamma_series(a, x);
  return 1.0f - calc_gamma_cf(a, x);
}

// snow_moments: optional outputs are nullptr when absent.  As in the
// Fortran, smoz reads the smo2 OUTPUT (callers always pass smo2 with smoz).
TEMPO_HD void snow_moments(const TempoParams& P, float rs, float tc,
                           TSP<float> smob, TSP<float> smoc, TSP<float> ns, TSP<float> smo0,
                           TSP<float> smo1, TSP<float> smo2, TSP<float> smoe, TSP<float> smof,
                           TSP<float> smog, TSP<float> smoz) {
  const float bm_s = PS(bm_s);
  float loga_, a_, b_, smo2_, m0, mrat, slam1, slam2, cc;
#define SA(i) PA1(sa, i)
#define SB(i) PA1(sb, i)
  *smob = rs * PS(oams);
  if (bm_s > 2.0f - 1.e-3f && bm_s < 2.0f + 1.e-3f) {
    loga_ = SA(1) + SA(2) * tc + SA(3) * bm_s + SA(4) * tc * bm_s + SA(5) * tc * tc
          + SA(6) * bm_s * bm_s + SA(7) * tc * tc * bm_s + SA(8) * tc * bm_s * bm_s
          + SA(9) * tc * tc * tc + SA(10) * bm_s * bm_s * bm_s;
    a_ = tempo_pow(10.0f, loga_);
    b_ = SB(1) + SB(2) * tc + SB(3) * bm_s + SB(4) * tc * bm_s + SB(5) * tc * tc
       + SB(6) * bm_s * bm_s + SB(7) * tc * tc * bm_s + SB(8) * tc * bm_s * bm_s
       + SB(9) * tc * tc * tc + SB(10) * bm_s * bm_s * bm_s;
    smo2_ = tempo_pow((*smob / a_), (1.0f / b_));
  } else {
    smo2_ = *smob;
  }
  if (smo2) *smo2 = smo2_;

#define TEMPO_SNOW_AB(cc)                                                              \
  loga_ = SA(1) + SA(2) * tc + SA(3) * (cc) + SA(4) * tc * (cc) + SA(5) * tc * tc        \
        + SA(6) * (cc) * (cc) + SA(7) * tc * tc * (cc) + SA(8) * tc * (cc) * (cc)        \
        + SA(9) * tc * tc * tc + SA(10) * (cc) * (cc) * (cc);                            \
  a_ = tempo_pow(10.0f, loga_);                                                                 \
  b_ = SB(1) + SB(2) * tc + SB(3) * (cc) + SB(4) * tc * (cc) + SB(5) * tc * tc           \
     + SB(6) * (cc) * (cc) + SB(7) * tc * tc * (cc) + SB(8) * tc * (cc) * (cc)           \
     + SB(9) * tc * tc * tc + SB(10) * (cc) * (cc) * (cc);

  cc = PA1(cse, 1);
  TEMPO_SNOW_AB(cc)
  *smoc = a_ * tempo_pow(smo2_, b_);

  loga_ = SA(1) + SA(2) * tc + SA(5) * tc * tc + SA(9) * tc * tc * tc;
  a_ = tempo_pow(10.0f, loga_);
  b_ = SB(1) + SB(2) * tc + SB(5) * tc * tc + SB(9) * tc * tc * tc;
  if (smo0) *smo0 = a_ * tempo_pow(smo2_, b_);

  loga_ = SA(1) + SA(2) * tc + SA(3) + SA(4) * tc + SA(5) * tc * tc + SA(6)
        + SA(7) * tc * tc + SA(8) * tc + SA(9) * tc * tc * tc + SA(10);
  a_ = tempo_pow(10.0f, loga_);
  b_ = SB(1) + SB(2) * tc + SB(3) + SB(4) * tc + SB(5) * tc * tc + SB(6)
     + SB(7) * tc * tc + SB(8) * tc + SB(9) * tc * tc * tc + SB(10);
  if (smo1) *smo1 = a_ * tempo_pow(smo2_, b_);

  m0 = *smob / *smoc;
  mrat = *smob * m0 * m0 * m0;
  slam1 = m0 * PS(lam0);
  slam2 = m0 * PS(lam1);
  if (ns) {
    *ns = mrat * PS(kap0) / slam1
        + mrat * PS(kap1) * tempo_pow(m0, PS(mu_s)) * PA1(csg, 15) / tempo_pow(slam2, PA1(cse, 15));
  }

  cc = PA1(cse, 13);
  TEMPO_SNOW_AB(cc)
  if (smoe) *smoe = a_ * tempo_pow(smo2_, b_);

  cc = PA1(cse, 16);
  TEMPO_SNOW_AB(cc)
  if (smof) *smof = a_ * tempo_pow(smo2_, b_);

  cc = PA1(cse, 17);
  TEMPO_SNOW_AB(cc)
  if (smog) *smog = a_ * tempo_pow(smo2_, b_);

  cc = PA1(cse, 3);
  TEMPO_SNOW_AB(cc)
  if (smoz) *smoz = a_ * tempo_pow(*smo2, b_);
#undef TEMPO_SNOW_AB
#undef SA
#undef SB
}

