TEMPO_HD bool tempo_any(TSP<const bool> l, int nz) {
  bool a = false;  // gpuwm.core.tempo_fast: branch-free (sm_120), same value
  for (int k = 1; k <= nz; ++k) a = a | l[k];
  return a;
}

// 828-848
TEMPO_HDN inline void aerosol_check_and_update(const TempoParams& P, const TempoCtx& C, int nz,
    TSP<const float> rho, TSP<const float> nwfa1d, TSP<const float> nifa1d, TSP<float> nwfa, TSP<float> nifa,
    TSP<float> nwfaten, TSP<float> nifaten) {
  for (int k = 1; k <= nz; ++k) {
    if (nwfa1d != nullptr) nwfa[k] = (nwfa1d[k] + nwfaten[k] * C.global_dt) * rho[k];
    if (nifa1d != nullptr) nifa[k] = (nifa1d[k] + nifaten[k] * C.global_dt) * rho[k];
    nwfa[k] = tmax(PS(nwfa_default) * rho[k], tmin(PS(aero_max) * rho[k], nwfa[k]));
    nifa[k] = tmax(PS(nifa_default) * rho[k], tmin(PS(aero_max) * rho[k], nifa[k]));
  }
}

// 851-941 (optional dt never passed by tempo_main: dt_ = global_dt)
TEMPO_HDN inline void cloud_check_and_update(const TempoParams& P, const TempoCtx& C, int nz,
    TSP<const float> rho, TSP<bool> l_qc, TSP<float> qc1d, TSP<float> nc1d, TSP<const float> ncsave,
    TSP<float> rc, TSP<float> nc, TSP<float> qcten, TSP<float> ncten, TSP<float> ilamc, TSP<float> mvd_c) {
  const float dt_ = C.global_dt;
  const float odt_ = 1.0f / dt_;
  int nu_c;
  float lamc, xdc;
  for (int k = 1; k <= nz; ++k) {
    bool hit_limit = false;
    if (qc1d[k] + qcten[k] * dt_ > PS(r1)) {
      l_qc[k] = true;
      rc[k] = (qc1d[k] + qcten[k] * dt_) * rho[k];
      qc1d[k] = qc1d[k] + qcten[k] * dt_;
      if (nc1d != nullptr) {
        nc[k] = tmax(PS(nt_c_min), (nc1d[k] + ncten[k] * dt_) * rho[k]);
        if (nc[k] <= PS(nt_c_min)) {
          hit_limit = true;
          nc[k] = PS(nt_c_min);
        }
        if (nc[k] > PS(nt_c_max)) {
          hit_limit = true;
          nc[k] = PS(nt_c_max);
        }
        nu_c = get_nuc(P, nc[k]);
        lamc = tempo_pow((nc[k] * PS(am_r) * PA2(ccg, 2, nu_c) * PA1(ocg1, nu_c) / rc[k]), PS(obmr));
        xdc = (PS(bm_r) + nu_c + 1.0f) / lamc;
        if (xdc < PS(d0c)) {
          lamc = PA2(cce, 2, nu_c) / PS(d0c);
          hit_limit = true;
        } else if (xdc > PS(d0r) * 2.0f) {
          lamc = PA2(cce, 2, nu_c) / (PS(d0r) * 2.0f);
          hit_limit = true;
        }
        nc[k] = PA2(ccg, 1, nu_c) * PA1(ocg2, nu_c) * rc[k] / PS(am_r) * tempo_pow(lamc, PS(bm_r));
        if (hit_limit) ncten[k] = (nc[k] / rho[k] - nc1d[k]) * odt_;
        nc1d[k] = tmax(PS(nt_c_min) / rho[k],
            tmin(PA2(ccg, 1, nu_c) * PA1(ocg2, nu_c) * qc1d[k] / PS(am_r) * tempo_pow(lamc, PS(bm_r)),
                 PS(nt_c_max) / rho[k]));
      } else {
        if (ncsave != nullptr) {
          nc[k] = ncsave[k];
        } else {
          nc[k] = PS(nt_c_l);
        }
      }
      nu_c = get_nuc(P, nc[k]);
      lamc = tempo_pow((nc[k] * PS(am_r) * PA2(ccg, 2, nu_c) * PA1(ocg1, nu_c) / rc[k]), PS(obmr));
      ilamc[k] = 1.0f / lamc;
      mvd_c[k] = tmax(tmin((3.0f + nu_c + 0.672f) * ilamc[k], PS(d0r)), PS(d0c));
    } else {
      l_qc[k] = false;
      rc[k] = PS(r1);
      nc[k] = PS(nt_c_min);
      mvd_c[k] = PS(d0c);
      ilamc[k] = 0.0f;
      qcten[k] = -qc1d[k] * odt_;
      qc1d[k] = 0.0f;
      if (nc1d != nullptr) {
        ncten[k] = -nc1d[k] * odt_;
        nc1d[k] = 0.0f;
      }
    }
  }
}

// 944-1009
TEMPO_HDN inline void rain_check_and_update(const TempoParams& P, const TempoCtx& C, int nz,
    TSP<const float> rho, TSP<bool> l_qr, TSP<float> qr1d, TSP<float> nr1d, TSP<float> rr, TSP<float> nr,
    TSP<float> qrten, TSP<float> nrten, TSP<float> ilamr, TSP<float> mvd_r) {
  float lamr = 0.0f;
  for (int k = 1; k <= nz; ++k) {
    bool hit_limit = false;
    if (qr1d[k] + qrten[k] * C.global_dt > PS(r1)) {
      l_qr[k] = true;
      rr[k] = (qr1d[k] + qrten[k] * C.global_dt) * rho[k];
      qr1d[k] = qr1d[k] + qrten[k] * C.global_dt;
      nr[k] = tmax(PS(r2), (nr1d[k] + nrten[k] * C.global_dt) * rho[k]);
      if (nr[k] <= PS(r2)) {
        hit_limit = true;
        mvd_r[k] = 1.0e-3f;
        lamr = (3.0f + PS(mu_r) + 0.672f) / mvd_r[k];
        nr[k] = PA1(crg, 2) * PS(org3) * rr[k] * tempo_pow(lamr, PS(bm_r)) / PS(am_r);
      }
      lamr = tempo_pow((PS(am_r) * PA1(crg, 3) * PS(org2) * nr[k] / rr[k]), PS(obmr));
      mvd_r[k] = (3.0f + PS(mu_r) + 0.672f) / lamr;
      if (mvd_r[k] > PS(d0r_max)) {
        hit_limit = true;
        mvd_r[k] = PS(d0r_max);
        lamr = (3.0f + PS(mu_r) + 0.672f) / mvd_r[k];
        nr[k] = PA1(crg, 2) * PS(org3) * rr[k] * tempo_pow(lamr, PS(bm_r)) / PS(am_r);
      } else if (mvd_r[k] < PS(d0r) * 0.75f) {
        hit_limit = true;
