extern "C" __global__ void nssl2_rain_self_collection(
    const float* __restrict__ air_density,
    const float* __restrict__ qr,
    float* __restrict__ qnr,
    float dt,
    int n)
{
    const int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx >= n) return;

