            mean_volume = maximum_mean_volume;
            number = __fdiv_rn(rho * rain, (mean_volume * rain_density));
        } else if (mean_volume < minimum_volume) {
            mean_volume = minimum_volume;
            number = __fdiv_rn(rho * rain, (mean_volume * rain_density));
