    float rain_number = fmaxf(qnr[idx], 0.0f) * rho;
    float graupel = fmaxf(qg[idx], 0.0f);
    float graupel_number = fmaxf(qng[idx], 0.0f) * rho;
    float graupel_volume = fmaxf(qvolg[idx], 0.0f) * rho;

