    full_theta[idx] = theta;
    qr[idx] = fmaxf(rain, 0.0f);
    qnr[idx] = fmaxf(rain_number, 0.0f) / rho;
    qg[idx] = fmaxf(graupel, 0.0f);
    qng[idx] = fmaxf(graupel_number, 0.0f) / rho;
