                || graupel_mean_volume > graupel_max_mean_volume) {
            graupel_mean_volume = fminf(
                graupel_max_mean_volume,
                fmaxf(graupel_min_volume, graupel_mean_volume));
            graupel_number = rho * graupel
                / (graupel_density * graupel_mean_volume);
