extern "C" __global__ void noahmp_write_arithmetic(
const long long* j,const long long* i,const int* isnow,
const float* rainbl,float dt,int n,long long nx,const bool* active,float* o_qfx, float* o_lh, float* o_smstav, float* o_smstot, float* o_sfcrunoff, float* o_udrunoff, float* o_albedo, float* o_canwat, float* o_acsnow, float* o_acsnom, float* o_pondingxy, float* o_q2mvxy, float* o_q2mbxy, float* o_rs, float* o_soilenergy, float* o_snowenergy, const float* v_ecan, const float* v_edir, const float* v_etran, const float* v_fcev, const float* v_fgev, const float* v_fctr, const float* v_runsrf, const float* v_runsub, const float* v_albedo, const float* v_canliq, const float* v_canice, const float* v_fpice, const float* v_qmelt, const float* v_ponding, const float* v_ponding1, const float* v_ponding2, const float* v_q2v, const float* v_q2b, const float* v_laisun, const float* v_laisha, const float* v_rb, const float* v_rssun, const float* v_rssha, const float* v_stc, const float* v_zsnso, const float* v_hcpct){
