o_sfcrunoff[p]=A(o_sfcrunoff[p],v_runsrf[c]);
o_udrunoff[p]=A(o_udrunoff[p],v_runsub[c]);
if(v_albedo[c]>-999.0f)o_albedo[p]=v_albedo[c];
o_canwat[p]=A(v_canliq[c],v_canice[c]);
o_acsnow[p]=A(o_acsnow[p],M(rainbl[p],v_fpice[c]));
