    o[4] = tauxb;
    o[5] = tauyb;
    o[6] = irb;
    o[7] = shb;
    o[8] = evb;
    o[9] = ghb;
    o[10] = t2mb;
    o[11] = q2b;
    o[12] = ehb2;
