        float x_adj2 = FMUL(x_adj, x_adj);
        bsum = FADD(FDIV(bsum, x_adj2), GFW_GAM_C1);
        bsum = FADD(FDIV(bsum, x_adj2), GFW_GAM_C0);
        exp_adj = FADD(exp_adj, FDIV(bsum, x_adj));
        return FADD(ret, FMUL(ret, gf_wrf_expm1(exp_adj)));
    }
}

