    for (int i = 0; i < NMP_NSNOW; ++i) {
        tksno[i] = 0.0f;
        cvsno[i] = 0.0f;
        snicev[i] = 0.0f;
        snliqv[i] = 0.0f;
        epore[i] = 0.0f;
        bdsnoi[i] = 0.0f;
