// ---------------------------------------------------------------------
// Contraction control-probe.  tests/test_p3_cuda.py compiles the module
// twice and compares these two kernels: under -fmad=false the infix form
// this file is written in must equal the explicit _rn intrinsics bit for
// bit, and under -fmad=true it must NOT.  That is what makes "plain
// operators are safe here" a measurement instead of an assumption.
// ---------------------------------------------------------------------
extern "C" __global__ void p3k_probe_infix(const float* __restrict__ a,
                                           const float* __restrict__ b,
                                           const float* __restrict__ c,
                                           float* __restrict__ o, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    o[i] = a[i] * b[i] + c[i];
}

extern "C" __global__ void p3k_probe_rn(const float* __restrict__ a,
                                        const float* __restrict__ b,
                                        const float* __restrict__ c,
                                        float* __restrict__ o, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    o[i] = __fadd_rn(__fmul_rn(a[i], b[i]), c[i]);
}
// P3 reflectivity as a PURE function of the state: the radar observation
// operator H_Z(x) for mp_physics=50/51.
//
// Compiled AFTER p3.cu in one translation unit (gpuwm/core/p3_device.py
// p3_reflectivity_module), so every helper below is the forecast port's own
// __device__ function, unchanged: p3_get_rain_dsd2, p3_impose_max_ni,
// p3_calc_bulk_rho_rime, p3_find_lt_1a and p3_access_lookup_table.  This
// file adds no Z formula of its own.
//
// What it is.  The Z half of p3_final_level (p3.cu, WRF
// module_mp_p3.F:4722-4895), replayed on LOCAL copies.  The forecast step
// evaluates that loop and updates the state in the same statements: it
// dumps sub-QSMALL rain and ice into vapour and theta, re-derives nr from
// the rain DSD limiter, imposes the total-Ni cap and clamps ni onto the
// lookup table's lambda limiters before ze_ice reads it.  Here every one of
// those values is formed in a register and nothing is written but zdbz, so
// evaluating the operator does not move the background it observes.
//
// Statement order is p3_final_level's, so on a state that has just left a
// P3 step (where those clamps are already applied) the result is the Z the
// step wrote, with the density formed from the state the operator is given
// (the step forms it from its entry temperature, :2322).
//
// Clear air.  A cell with neither rain nor ice above QSMALL keeps the two
// accumulator seeds, ze_rain = ze_ice = 1e-22 mm6 m-3 (:2286-2287), and
// reads 10*log10(2e-22*1e18) = -36.9897 dBZ.  That is the scheme's own
// zero-hydrometeor reflectivity, and it is the operator's ONE clear-air
// value in every cell.  The forecast field additionally holds the -99.0
// entry initialisation (:2278) through columns its no-hydrometeor skip
// (:3972) never diagnoses; that sentinel is not a reflectivity and the
// operator does not reproduce it, which is what gives P3 one floor.

template <int NCAT> __device__ void p3_reflectivity_body(
    const float* __restrict__ qr, const float* __restrict__ nr,
    const float* __restrict__ qi, const float* __restrict__ qir,
    const float* __restrict__ ni, const float* __restrict__ qib,
    const float* __restrict__ th, const float* __restrict__ pres,
    const float* __restrict__ qi2, const float* __restrict__ qir2,
    const float* __restrict__ ni2, const float* __restrict__ qib2,
    const float* __restrict__ itab, float* __restrict__ zdbz, int n)
{
    const int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= n) return;

    // Atmospheric variables as the step forms them (:2293-2295, :2322-2323).
    const float tm = r_pow(pres[c] * 1.0e-5f, P3_RD * P3_INV_CP);
    const float t = th[c] * tm;
    const float rho = pres[c] / (P3_RD * t);
    const float inv_rho = 1.0f / rho;
    float ze_ice = 1.0e-22f, ze_rain = 1.0e-22f;                     // :2286-2287

    const float q_r = qr[c];
    if (q_r >= P3_QSMALL) {
        float mu_r, lamr, cdistr, logn0r, nrg = nr[c];
        // the authority passes the LITERAL iSPF = 1. here (:4739)
        p3_get_rain_dsd2(&nrg, q_r, 1.0f, &mu_r, &lamr, &cdistr, &logn0r);
        float l2 = lamr * lamr;
        float lam6 = (l2 * l2) * l2;                     // :4756, integer **6
        ze_rain = rho * nrg * (mu_r + 6.0f) * (mu_r + 5.0f)
                  * (mu_r + 4.0f) * (mu_r + 3.0f) * (mu_r + 2.0f)
                  * (mu_r + 1.0f) / lam6;
        ze_rain = fmaxf(ze_rain, 1.0e-22f);
    }

    const float* qip[2] = {qi, qi2};
    const float* qirp[2] = {qir, qir2};
    const float* qibp[2] = {qib, qib2};
    float number[NCAT];
    if (NCAT == 1) number[0] = p3_impose_max_ni(ni[c], inv_rho);
    else {
        number[0] = ni[c]; number[1] = ni2[c];
        if (p3_sum<NCAT>(number) * rho >= P3_MAX_TOTAL_NI) {
            float scale = P3_MAX_TOTAL_NI * inv_rho / p3_sum<NCAT>(number);
            for (int cat = 0; cat < NCAT; ++cat)
                number[cat] *= fminf(scale, 1.0f);
        }
    }
    for (int cat = 0; cat < NCAT; ++cat) {
    float n_i = number[cat];
    const float q_i = qip[cat][c];
    if (q_i >= P3_QSMALL) {
        n_i = fmaxf(n_i, P3_NSMALL);
        float rhop, qq = qirp[cat][c], bb = qibp[cat][c];
        p3_calc_bulk_rho_rime(q_i, &qq, &bb, &rhop);
        int dumi, dumjj, dumii;
        float d1, d4, d5;
        p3_find_lt_1a(q_i, n_i, qq, rhop, &dumi, &dumjj, &dumii,
                      &d1, &d4, &d5);
        float f1pr09 = p3_access_lookup_table(itab, dumjj, dumii, dumi, 7,
                                              d1, d4, d5);
        float f1pr10 = p3_access_lookup_table(itab, dumjj, dumii, dumi, 8,
                                              d1, d4, d5);
        float f1pr13 = p3_access_lookup_table(itab, dumjj, dumii, dumi, 9,
                                              d1, d4, d5);
        n_i = fminf(n_i, f1pr09 * q_i);
        n_i = fmaxf(n_i, f1pr10 * q_i);
        ze_ice = ze_ice + 0.1892f * f1pr13 * n_i * rho;
        ze_ice = fmaxf(ze_ice, 1.0e-22f);
    }

    }

    zdbz[c] = 10.0f * p3_log10((ze_rain + ze_ice) * 1.0e18f);
}

extern "C" __global__ void p3k_reflectivity(
    const float* qr, const float* nr, const float* qi, const float* qir,
    const float* ni, const float* qib, const float* th, const float* pres,
    const float* itab, float* zdbz, int n)
{ p3_reflectivity_body<1>(qr,nr,qi,qir,ni,qib,th,pres,
                          nullptr,nullptr,nullptr,nullptr,itab,zdbz,n); }

extern "C" __global__ void p3k_reflectivity_c2(
    const float* qr, const float* nr, const float* qi, const float* qir,
    const float* ni, const float* qib, const float* th, const float* pres,
    const float* qi2, const float* qir2, const float* ni2, const float* qib2,
    const float* itab, float* zdbz, int n)
{ p3_reflectivity_body<2>(qr,nr,qi,qir,ni,qib,th,pres,
                          qi2,qir2,ni2,qib2,itab,zdbz,n); }
// WRF module_mp_p3.F:4795-4846, three-moment closure on local values.
// No prognostic or lookup table is modified by this diagnostic.
extern "C" __global__ void p3k_reflectivity_3mom(
    const float* __restrict__ qr, const float* __restrict__ nr,
    const float* __restrict__ qi, const float* __restrict__ qir,
    const float* __restrict__ ni, const float* __restrict__ qib,
    const float* __restrict__ th, const float* __restrict__ pres,
    const float* __restrict__ qzi, const float* __restrict__ itab3,
    float* __restrict__ zdbz, int n)
{
    const int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= n) return;
    const float tm = r_pow(pres[c] * 1.0e-5f, P3_RD * P3_INV_CP);
    const float t = th[c] * tm;
    const float rho = pres[c] / (P3_RD * t);
    const float inv_rho = 1.0f / rho;
    float ze_ice = 1.0e-22f, ze_rain = 1.0e-22f;
    const float q_r = qr[c];
    if (q_r >= P3_QSMALL) {
        float mu_r, lamr, cdistr, logn0r, nrg = nr[c];
        p3_get_rain_dsd2(&nrg, q_r, 1.0f, &mu_r, &lamr, &cdistr, &logn0r);
        float l2 = lamr * lamr;
        float lam6 = (l2 * l2) * l2;
        ze_rain = rho * nrg * (mu_r + 6.0f) * (mu_r + 5.0f)
                  * (mu_r + 4.0f) * (mu_r + 3.0f) * (mu_r + 2.0f)
                  * (mu_r + 1.0f) / lam6;
        ze_rain = fmaxf(ze_rain, 1.0e-22f);
    }
    float n_i = p3_impose_max_ni(ni[c], inv_rho);
    const float q_i = qi[c];
    if (q_i >= P3_QSMALL) {
        n_i = fmaxf(n_i, P3_NSMALL);
        float rhop, qq = qir[c], bb = qib[c];
        p3_calc_bulk_rho_rime(q_i, &qq, &bb, &rhop);
        int dumi, dumjj, dumii, dumzz;
        float d1, d4, d5, d6, rho_bulk;
        p3_find_lt_1a(q_i, n_i, qq, rhop, &dumi, &dumjj, &dumii,
                      &d1, &d4, &d5);
        // The Registry carries sqrt(N*Z), not Z (WRF wrapper :826-838).
        const float z_entry = ni[c] >= P3_QSMALL
            ? (qzi[c] * qzi[c]) / ni[c] : 0.0f;
        const float z_i = fmaxf(z_entry, P3_ZSMALL);
        p3_mu_i_iterate(itab3, q_i, n_i, z_i, dumjj, dumii, dumi,
                        d1, d4, d5, &dumzz, &d6, &rho_bulk);
        const float f1pr09 = p3_access_lookup_table_3mom(
            itab3, dumzz, dumjj, dumii, dumi, 7, d1, d4, d5, d6);
        const float f1pr10 = p3_access_lookup_table_3mom(
            itab3, dumzz, dumjj, dumii, dumi, 8, d1, d4, d5, d6);
        const float f1pr13 = p3_access_lookup_table_3mom(
            itab3, dumzz, dumjj, dumii, dumi, 9, d1, d4, d5, d6);
        n_i = fminf(n_i, f1pr09 * q_i);
        n_i = fmaxf(n_i, f1pr10 * q_i);
        ze_ice = ze_ice + 0.1892f * f1pr13 * n_i * rho;
        ze_ice = fmaxf(ze_ice, 1.0e-22f);
    }
    zdbz[c] = 10.0f * p3_log10((ze_rain + ze_ice) * 1.0e18f);
}

#include "tempo_column.cuh"
#include "tempo_cloud_ml.cuh"
#include "../glibc_flt32.cuh"
#define NFLD 17
struct ColState { double f[NFLD][TEMPO_NZP]; };

// fields: NFLD device pointers to (nz, ny, nx) arrays of T, column = j*nx+i
template <typename T>
__device__ void pack_impl(const T* const* fields, int nz, int ncol_total, int col0, int ncol,
                          ColState* S) {
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= ncol) return;
  long long g = col0 + c;
  for (int j = 0; j < NFLD; ++j) {
    const T* a = fields[j];
    S[c].f[j][0] = 0.0;
    for (int k = 1; k <= nz; ++k) S[c].f[j][k] = (double)a[(long long)(k - 1) * ncol_total + g];
    for (int k = nz + 1; k < TEMPO_NZP; ++k) S[c].f[j][k] = 0.0;
  }
}
template <typename T>
__device__ void unpack_impl(T* const* fields, const int* which, int nwhich, int nz,
                            int ncol_total, int col0, int ncol, const ColState* S,
                            const TempoWork* W, double* sfc, double* coldiag) {
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= ncol) return;
  long long g = col0 + c;
  for (int m = 0; m < nwhich; ++m) {
    T* a = fields[m];
    int j = which[m];
    for (int k = 1; k <= nz; ++k) a[(long long)(k - 1) * ncol_total + g] = (T)S[c].f[j][k];
  }
  const TempoWork& w = W[c];
  double mh = w.max_hail_diameter[1];
  for (int k = 2; k <= nz; ++k) mh = w.max_hail_diameter[k] > mh ? w.max_hail_diameter[k] : mh;
  double s[8] = {w.rain_precip, w.ice_liquid_equiv_precip, w.snow_liquid_equiv_precip,
                 w.graupel_liquid_equiv_precip, w.frz_rain_precip, w.frozen_fraction,
                 w.max_hail_diameter[1], mh};
  for (int m = 0; m < 8; ++m) sfc[(long long)m * ncol_total + g] = s[m];
  for (int k = 1; k <= nz; ++k) {
    long long o = (long long)(k - 1) * ncol_total + g;
    long long plane = (long long)nz * ncol_total;
    coldiag[o] = w.refl10cm[k];
    coldiag[plane + o] = w.re_cloud[k];
    coldiag[2 * plane + o] = w.re_ice[k];
    coldiag[3 * plane + o] = w.re_snow[k];
  }
}
extern "C" __global__ void tempo_pack_f32(const float* const* f, int nz, int nt, int c0, int n, ColState* S) { pack_impl<float>(f, nz, nt, c0, n, S); }
extern "C" __global__ void tempo_pack_f64(const double* const* f, int nz, int nt, int c0, int n, ColState* S) { pack_impl<double>(f, nz, nt, c0, n, S); }
extern "C" __global__ void tempo_unpack_f32(float* const* f, const int* wh, int nw, int nz, int nt, int c0, int n, const ColState* S, const TempoWork* W, double* sfc, double* cd) { unpack_impl<float>(f, wh, nw, nz, nt, c0, n, S, W, sfc, cd); }
extern "C" __global__ void tempo_unpack_f64(double* const* f, const int* wh, int nw, int nz, int nt, int c0, int n, const ColState* S, const TempoWork* W, double* sfc, double* cd) { unpack_impl<double>(f, wh, nw, nz, nt, c0, n, S, W, sfc, cd); }

// Host float32 theta/Exner and m3/kg volume, TEMPO float64 column arithmetic.
// Keep the temperature and volume intermediates in the column, as the
// public tempo_run(theta, pii) interface does. Round only on host writeback.
extern "C" __global__ void tempo_pack_adapter(const float* const* f, const float* pii,
        const float* emission, double dt,
        int nz, int nt, int c0, int n, ColState* S) {
  pack_impl<float>(f, nz, nt, c0, n, S);
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= n) return;
  for (int k = 1; k <= nz; ++k) {
    long long o = (long long)(k - 1) * nt + c0 + c;
    S[c].f[0][k] *= (double)pii[o];
    S[c].f[16][k] *= 1000.0;
  }
  if (emission) S[c].f[13][1] = __dadd_rn(S[c].f[13][1],
                          __dmul_rn((double)emission[c0+c], dt));
}
extern "C" __global__ void tempo_unpack_adapter(float* const* f, const int* wh, int nw,
        const float* pii, const float* emission, double dt,
        int nz, int nt, int c0, int n, ColState* S, const TempoWork* W,
        double* sfc, double* cd) {
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= n) return;
  // tempo_aerosol_surface_emissions after tempo_run, before float32 storage.
  if (emission) S[c].f[13][1] = __dadd_rn(S[c].f[13][1],
                          __dmul_rn((double)emission[c0+c], dt));
  for (int k = 1; k <= nz; ++k) {
    long long o = (long long)(k - 1) * nt + c0 + c;
    S[c].f[0][k] /= (double)pii[o];
    S[c].f[16][k] *= 1.0e-3;
  }
  unpack_impl<float>(f, wh, nw, nz, nt, c0, n, S, W, sfc, cd);
}
extern "C" __global__ void tempo_adapter_exner(const float* p, float* pii, int n,
                                               float p0, float rcp) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < n) pii[i] = gfk_pow(__fdiv_rn(p[i], p0), rcp);
}

extern "C" __global__ void tempo_columns(const double* blob, TempoCtx C, int ncol, int nz,
                                         int first_global_col, ColState* S, TempoWork* W,
                                         const float* qc_bl, const float* fraction_bl, int nt) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= ncol) return;
  TempoParams P{reinterpret_cast<const TempoBlob*>(blob)};
  TempoCtx c = C;
#if TEMPO_GEN < 325
  if (first_global_col + i != 0) c.first_call_main = 0;  // Fortran SAVE flag: first column only
#endif
  ColState& s = S[i];
  tempo_main_column(P, c, nz, W[i], s.f[4], s.f[5], s.f[7], s.f[6], s.f[8], s.f[9], s.f[16],
                    s.f[10], s.f[11], s.f[12], s.f[15], s.f[13], s.f[14], s.f[0], s.f[1],
                    s.f[2], s.f[3]);
  if (qc_bl && fraction_bl)
    tempo_subgrid_cloud_radii(P, c, nz, W[i], s.f[5], s.f[6], s.f[7], s.f[8],
                             s.f[12], s.f[2], qc_bl, fraction_bl, nt, first_global_col+i);
}
// Initial-state radar diagnosis: prepare only the native PSDs, then call
// the same reflectivity_10cm used by tempo_main_column. Packed fields are
// private copies; no tendencies, sedimentation or model writes occur.
extern "C" __global__ void tempo_initial_refl(const double* blob, TempoCtx C,
    int n, int nz, int c0, int nt, ColState* S, TempoWork* work, float* out) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) return;
  TempoParams P{reinterpret_cast<const TempoBlob*>(blob)};
  ColState& s = S[i];
  TempoWork& W = work[i];
  for (int k = 1; k <= nz; ++k) {
    W.temp[k] = s.f[0][k];
    W.qv[k] = tmax(PS(min_qv), s.f[4][k]);
    W.pres[k] = s.f[1][k];
    W.rho[k] = PS(roverrv) * W.pres[k] /
      (PS(rdry) * W.temp[k] * (W.qv[k] + PS(roverrv)));
    W.refl10cm[k] = -35.0;
  }
  rain_check_and_update(P, C, nz, W.rho, W.l_qr, s.f[6], s.f[11],
    W.rr, W.nr, W.qrten, W.nrten, W.ilamr, W.mvd_r);
  snow_check_and_update(P, C, nz, W.rho, W.l_qs, s.f[8], W.rs, W.qsten);
  double sq = 0.0, sn = 0.0, sb = 0.0;
  for (int k = 1; k <= nz; ++k) {
    sq += s.f[9][k]; sn += s.f[15][k]; sb += s.f[16][k];
    if (W.l_qs[k]) {
      double tc = tmin(-0.1, W.temp[k] - PS(t0));
      snow_moments(P, W.rs[k], tc, &W.smob[k], &W.smoc[k], nullptr,
        nullptr, nullptr, &W.smo2[k], nullptr, nullptr, nullptr, &W.smoz[k]);
    }
  }
  if (sq > PS(r1) && sn < PS(eps) && sb < PS(eps))
    graupel_init(P, nz, W.rho, s.f[9], s.f[15], s.f[16]);
  graupel_check_and_update(P, C, nz, W.rho, W.l_qg, s.f[9], s.f[15], s.f[16],
    W.rg, W.ng, W.rb, W.idx_bg, W.qgten, W.ngten, W.qbten, W.ilamg, W.mvd_g);
#if TEMPO_GEN >= 325
  // The initial state carries no split hail: graupel holds it all.
  for (int k = 0; k < TEMPO_NZP; ++k) W.l_qh[k] = false;
  reflectivity_10cm(P, C, nz, C.refl10cm_from_melting_flag, W.temp,
    W.l_qr, W.rr, W.nr, W.ilamr, W.l_qs, W.rs, W.smoc, W.smob, W.smoz,
    W.l_qg, W.rg, W.ng, W.idx_bg, W.ilamg, W.l_qh, W.nh, W.ilamh, W.refl10cm);
#else
  reflectivity_10cm(P, C, nz, C.refl10cm_from_melting_flag, W.temp,
    W.l_qr, W.rr, W.nr, W.ilamr, W.l_qs, W.rs, W.smoc, W.smob, W.smoz,
    W.l_qg, W.rg, W.ng, W.idx_bg, W.ilamg, W.refl10cm);
#endif
  for (int k = 1; k <= nz; ++k)
    out[(long long)(k-1)*nt+c0+i] = (float)W.refl10cm[k];
}
extern "C" __global__ void tempo_sizes(long long* out) {
  out[0] = sizeof(TempoWork); out[1] = sizeof(ColState); out[2] = sizeof(TempoCtx);
  out[3] = TEMPO_NZ_MAX;
}
// NOAA MPAS 1d6e370e mpas_atmphys_init_tempo.F:172-178. Input climatology
// is retained; bounds apply to its emissions only. Host storage is float32.
extern "C" __global__ void tempo_mpas_emission_init(const double* blob,
    const float* nwfa, const double* depth, const double* area, float* emission, int n) {
  int i = blockIdx.x*blockDim.x + threadIdx.x;
  if (i >= n) return;
  TempoParams P{reinterpret_cast<const TempoBlob*>(blob)};
  double dz = tmax(9.0, (double)depth[i]);
  emission[i] = (float)(tmax(PS(nwfa_default), tmin(PS(aero_max), (double)nwfa[i]))
                      * 0.000196 * (5.0/dz) * (area[i]/9.0e6));
}

extern "C" __global__ void noahmp_snow_tinit_conduction(
    const int n, const int* __restrict__ isnow, const float* __restrict__ zsnso,
    const float* __restrict__ tg, const float* __restrict__ tslb1,
    const float* __restrict__ xice, const float xice_threshold,
    float* __restrict__ tsno)
{
    // zsnso and tsno are layer-major slabs: layer k of column c at k*n + c.
    const int c = blockDim.x * blockIdx.x + threadIdx.x;
    if (c >= n) return;
    const int nl = -isnow[c];
    if (nl <= 0 || xice[c] >= xice_threshold) return;
    const float h = -zsnso[2 * n + c];
    if (!(h > 0.0f)) return;
    const float t0 = tg[c], dt = tslb1[c] - t0;
    float zprev = 0.0f;
    for (int k = 3 - nl; k < 3; ++k) {
        const float zb = -zsnso[k * n + c];
        const float zm = __fmul_rn(0.5f, __fadd_rn(zprev, zb));
        const float t = __fadd_rn(t0, __fmul_rn(dt, __fdiv_rn(zm, h)));
        tsno[k * n + c] = fminf(t, 273.16f);
        zprev = zb;
    }
}

